import{_ as e,o as t,c as r,a2 as d}from"./chunks/framework.BaXgE4DV.js";const h=JSON.parse('{"title":"결정 기록","description":"","frontmatter":{},"headers":[],"relativePath":"decisions.md","filePath":"decisions.md","lastUpdated":1792255292000}'),a={name:"decisions.md"};function i(s,o,c,l,n,g){return t(),r("div",null,[...o[0]||(o[0]=[d('<h1 id="결정-기록" tabindex="-1">결정 기록 <a class="header-anchor" href="#결정-기록" aria-label="Permalink to &quot;결정 기록&quot;">​</a></h1><p>주요 설계 결정을 ADR(Architecture Decision Record) 형식으로 남깁니다. 새 결정은 아래에 번호를 이어 붙이고, 뒤집힌 결정은 지우지 말고 &quot;대체됨&quot;으로 표시합니다.</p><table tabindex="0"><thead><tr><th>#</th><th>결정</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td><a href="#adr-1">Gemini를 Cloud Functions로 이전</a></td><td>대체됨 (ADR-10)</td></tr><tr><td>2</td><td><a href="#adr-2">gratitudes get/list 규칙 분리</a></td><td>적용</td></tr><tr><td>3</td><td><a href="#adr-3">Circle 멤버십은 callable로 서버에서만 변경</a></td><td>적용 (1단계)</td></tr><tr><td>4</td><td><a href="#adr-4">Circle 삭제 시 감사 글 보존</a></td><td>적용</td></tr><tr><td>5</td><td><a href="#adr-5">feedMeta로 로딩 상태 구분</a></td><td>적용</td></tr><tr><td>6</td><td><a href="#adr-6">외부 공유는 작성자 opt-in</a></td><td>적용 (1단계)</td></tr><tr><td>7</td><td><a href="#adr-7">통계는 서버에서 KST 기준 계산</a></td><td>적용 (1단계)</td></tr><tr><td>8</td><td><a href="#adr-8">모바일 앱은 Capacitor</a></td><td>진행 중 (3단계)</td></tr><tr><td>9</td><td><a href="#adr-9">개발 문서는 비공개 저장소의 docs/ → 공개 Pages</a></td><td>적용</td></tr><tr><td>10</td><td><a href="#adr-10">AI 글쓰기 기능 제거, 질문으로 쓰기로 대체</a></td><td>적용 (2026-10-07 배포)</td></tr><tr><td>11</td><td><a href="#adr-11">질문은 사용자 제안 + 운영자 선정</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>12</td><td><a href="#adr-12">감사는 기본 개인 기록, Circle 공유는 선택</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>13</td><td><a href="#adr-13">화면을 막지 않는 시작과 기기 캐시</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>14</td><td><a href="#adr-14">신고·차단·자동 숨김</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>15</td><td><a href="#adr-15">계정 삭제 범위(삭제 vs 익명화)</a></td><td>적용 (2026-10-08 배포)</td></tr><tr><td>16</td><td><a href="#adr-16">매일 알림: 웹 15분 단위, 앱 휴대폰 자체 알림</a></td><td>웹 적용 (2026-10-08 배포), 앱 코드 완료 (3단계, 배포 전)</td></tr><tr><td>17</td><td><a href="#adr-17">앱 로그인은 네이티브 시트 + JS SDK 세션 (<code>skipNativeAuth</code>)</a></td><td>코드 완료 (3단계, 배포 전)</td></tr><tr><td>21</td><td><a href="#adr-21">별명으로 참여하는 공개 Circle &quot;모두의 감사방&quot;</a></td><td>배포 (2026-10-17, 기능 꺼 둠)</td></tr><tr><td>22</td><td><a href="#adr-22">작성자 표시는 지금의 이름·사진·별명을 따름</a></td><td>적용 (2026-10-17 배포, 기존 글 백필 완료)</td></tr><tr><td>23</td><td><a href="#adr-23">배지 보상: 공감 이모지 (서버 지급, 규칙 확인, 원격 켜기)</a></td><td>배포 (2026-10-17, 보상 꺼 둠)</td></tr><tr><td>24</td><td><a href="#adr-24">이름 옆 꾸밈: 배지 호칭과 &quot;n일째 감사 중&quot;</a></td><td>적용 (2026-10-17 배포, 앱은 iOS 1.0.1 (5)부터)</td></tr><tr><td>31</td><td><a href="#adr-31">모두의 감사방 오늘의 주제: 서버만 쓰는 주제 문서, 답은 감사 글</a></td><td>코드 완료 (배포 전, 앱은 iOS 1.0.1 (5)부터)</td></tr><tr><td>33</td><td><a href="#adr-33">글마다 정해진 시각의 일회성 작업은 Cloud Tasks</a></td><td>적용 (배포 전)</td></tr><tr><td>35</td><td><a href="#adr-35">시즌 질문은 앱의 날짜 계산 + 앱 안 사본, 시드는 &quot;다른 질문&quot;과 예전 앱용</a></td><td>배포 전 (앱은 iOS 1.0.1 (5)부터)</td></tr><tr><td>36</td><td><a href="#adr-36">PR마다 테스트, 변경 이력은 PR별 조각 파일</a></td><td>적용 (2026-10, CI 전용)</td></tr><tr><td>37</td><td><a href="#adr-37">이미지 테마: 배지로 서버가 지급, 고르기와 그리기는 기기에서</a></td><td>코드 완료 (배포 전, 앱은 iOS 1.0.1 (5)부터)</td></tr></tbody></table><h2 id="adr-1" tabindex="-1">ADR-1 Gemini를 Cloud Functions로 이전 <a class="header-anchor" href="#adr-1" aria-label="Permalink to &quot;ADR-1 Gemini를 Cloud Functions로 이전 {#adr-1}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">대체됨</p><p>AI 글쓰기 기능을 없애면서 이 결정은 더 이상 적용되지 않습니다. → <a href="#adr-10">ADR-10</a></p></div><ul><li><strong>결정</strong>: Gemini API는 클라이언트가 아니라 callable 함수(<code>generateGratitude</code>)에서만 호출합니다. 키는 Secret Manager 비밀값 <code>GEMINI_API_KEY</code>로 둡니다.</li><li><strong>이유</strong>: 클라이언트 번들에 들어간 키는 누구나 꺼내 쓸 수 있습니다. 서버를 거치면 키를 숨기고, 사용자별 일일 한도(20회)·캐시·시간 제한으로 비용을 통제하고, 실패 시 fallback으로 UX를 지킬 수 있습니다. 질문은 서버의 질문 풀에서 골라 모델 호출 자체를 줄였습니다.</li><li><strong>대안</strong>: 클라이언트에서 직접 호출(키 노출), 클라이언트용 AI SDK + App Check(한도·캐시·프롬프트를 서버에서 통제하기 어려움).</li></ul><h2 id="adr-2" tabindex="-1">ADR-2 gratitudes get/list 규칙 분리 <a class="header-anchor" href="#adr-2" aria-label="Permalink to &quot;ADR-2 gratitudes get/list 규칙 분리 {#adr-2}&quot;">​</a></h2><ul><li><strong>결정</strong>: <code>gratitudes</code> 읽기 규칙을 <code>allow get</code>과 <code>allow list</code>로 나눕니다.</li><li><strong>이유</strong>: Firestore는 단건 읽기는 실제 문서로, 쿼리는 &quot;돌려줄 수 있는 모든 문서&quot;로 평가합니다. 하나의 <code>read</code> 규칙으로는 둘 다 정확히 표현하기 어렵습니다. 분리하면 get은 작성자·현재 멤버로 판단하고, list는 <code>userId ==</code> 또는 <code>groupId ==</code> 쿼리 형태만 허용해 교차 읽기를 최소화할 수 있습니다.</li><li><strong>대안</strong>: 단일 <code>read</code> 규칙(쿼리가 불필요하게 거부되거나 규칙이 느슨해짐), 다중 그룹 <code>in</code> 쿼리 허용(교차 읽기 10회 한도 초과 위험).</li></ul><h2 id="adr-3" tabindex="-1">ADR-3 Circle 멤버십은 callable로 서버에서만 변경 <a class="header-anchor" href="#adr-3" aria-label="Permalink to &quot;ADR-3 Circle 멤버십은 callable로 서버에서만 변경 {#adr-3}&quot;">​</a></h2><ul><li><strong>결정</strong>: <code>groups.memberIds</code>, <code>users.groupIds</code>, <code>inviteCodes</code>, <code>removedIds</code>는 Circle callable 7종(Admin SDK, 트랜잭션)만 바꿉니다. 클라이언트 쓰기는 규칙에서 거부합니다.</li><li><strong>이유</strong>: 참여 하나에도 초대 코드의 존재·만료·사용 횟수, Circle 정원, 사용자의 Circle 수, 내보낸 사용자 여부를 확인하고 세 문서를 원자적으로 바꿔야 합니다. 보안 규칙만으로는 이 검증과 원자성을 보장하기 어렵고, 규칙이 복잡해질수록 테스트·유지보수도 어렵습니다. 서버로 옮기면 한국어 오류 메시지도 일관되게 줄 수 있습니다.</li><li><strong>대안</strong>: 규칙에서 초대 코드를 교차 조회해 클라이언트가 직접 쓰기(원자성·정원·사용 횟수 검증이 어려움), <code>inviteCodes</code>에 관리자 ID 비정규화(동기화 부담).</li></ul><h2 id="adr-4" tabindex="-1">ADR-4 Circle 삭제 시 감사 글 보존 <a class="header-anchor" href="#adr-4" aria-label="Permalink to &quot;ADR-4 Circle 삭제 시 감사 글 보존 {#adr-4}&quot;">​</a></h2><ul><li><strong>결정</strong>: Circle을 삭제해도 그 Circle에 쓴 감사 글은 지우지 않습니다. 작성자는 계속 자기 글을 읽을 수 있습니다.</li><li><strong>이유</strong>: 감사 글은 Circle의 것이 아니라 작성자의 기록입니다. 관리자의 삭제로 다른 사람의 기록이 사라지면 안 됩니다. 규칙의 &quot;작성자는 항상 읽기 가능&quot; 분기가 이를 보장합니다.</li><li><strong>대안</strong>: 글까지 함께 삭제(작성자 기록 손실, 대량 삭제 비용), 글을 개인 글로 이동(<code>groupId</code> 일괄 수정 비용).</li></ul><h2 id="adr-5" tabindex="-1">ADR-5 feedMeta로 로딩 상태 구분 <a class="header-anchor" href="#adr-5" aria-label="Permalink to &quot;ADR-5 feedMeta로 로딩 상태 구분 {#adr-5}&quot;">​</a></h2><ul><li><strong>결정</strong>: 피드 상태(현재 <code>groupStore.feeds[key]</code>, 처음에는 <code>feedMeta[groupId]</code>)가 없으면(undefined) 로딩 중, 있으면 데이터 수신 완료로 봅니다.</li><li><strong>이유</strong>: 빈 배열 하나로는 &quot;아직 안 옴&quot;과 &quot;글이 없음&quot;을 구분할 수 없어, 피드가 잠깐 빈 화면으로 보였다가 채워지는 문제가 생깁니다. 구독 오류(권한 상실 등) 때는 <code>error</code>를 표시한 상태를 넣어 로딩이 끝나되 &quot;글이 없음&quot;으로 보이지 않게 합니다. 내 기록이 기본 탭이 된 뒤로는 오류를 빈 피드로 보이면 &quot;기록이 사라졌다&quot;로 읽히기 때문입니다.</li><li><strong>대안</strong>: 별도 <code>loading</code> 플래그를 Circle마다 관리(상태가 늘어나고 어긋나기 쉬움).</li></ul><h2 id="adr-6" tabindex="-1">ADR-6 외부 공유는 작성자 opt-in <a class="header-anchor" href="#adr-6" aria-label="Permalink to &quot;ADR-6 외부 공유는 작성자 opt-in {#adr-6}&quot;">​</a></h2><ul><li><strong>결정</strong>: 공유 링크는 작성자가 공개한 것만 보여 줍니다. 감사 글은 <code>isPublic</code>, 캘린더 월·배지는 <code>publicShares/{uid}</code>에 등록된 것만. 공개하지 않은 것은 내용 없이 &quot;비공개&quot; 안내(<code>noindex</code>)를 돌려줍니다.</li><li><strong>이유</strong>: 감사 글은 Circle 안에서 나누려고 쓴 개인적인 기록입니다. 링크가 다른 곳으로 퍼지더라도 작성자가 명시적으로 고른 것만 밖에 보여야 합니다. 공개를 취소하면 1분 안에 반영되도록 공유 페이지 캐시를 짧게 둡니다.</li><li><strong>대안</strong>: 기본 공개 + 비공개 전환(작성자가 모르는 사이 노출), 공유마다 별도 토큰 URL 발급(구현·관리 복잡도).</li></ul><h2 id="adr-7" tabindex="-1">ADR-7 통계는 서버에서 KST 기준 계산 <a class="header-anchor" href="#adr-7" aria-label="Permalink to &quot;ADR-7 통계는 서버에서 KST 기준 계산 {#adr-7}&quot;">​</a></h2><ul><li><strong>결정</strong>: <code>userStats</code>(연속일, 월별 수)는 <code>onGratitudeCreated</code> 트리거가 KST 날짜로 계산하고, 클라이언트는 읽기만 합니다. 표시용 판단(연속일이 살아 있는지)도 같은 KST 규칙을 씁니다.</li><li><strong>이유</strong>: 클라이언트가 쓰면 값을 조작할 수 있고, 기기 시간대마다 &quot;오늘&quot;이 달라 연속일이 어긋납니다. 사용자 대부분이 한국에 있으므로 KST를 단일 기준으로 삼았습니다. 트리거는 마커로 멱등하게 만들어 중복 집계를 막습니다.</li><li><strong>대안</strong>: 클라이언트 계산(조작·시간대 불일치), 사용자별 시간대 저장(복잡도 대비 이득이 작음), 매번 글 목록으로 다시 계산(읽기 비용).</li></ul><h2 id="adr-8" tabindex="-1">ADR-8 모바일 앱은 Capacitor <a class="header-anchor" href="#adr-8" aria-label="Permalink to &quot;ADR-8 모바일 앱은 Capacitor {#adr-8}&quot;">​</a></h2><ul><li><strong>결정</strong>: iOS·Android 앱은 Capacitor로 기존 React 앱을 감싸 만듭니다. 로그인·푸시·딥링크·공유는 네이티브 플러그인으로 처리합니다.</li><li><strong>이유</strong>: 한 사람이 웹과 두 앱을 함께 유지해야 하므로 코드 재사용이 가장 중요합니다. Capacitor는 지금의 React·Firebase JS SDK 코드를 거의 그대로 쓰면서 스토어 출시에 필요한 네이티브 기능을 붙일 수 있습니다.</li><li><strong>대안</strong>: React Native 재작성(UI 전면 재작성), 네이티브 Swift·Kotlin(유지 인력 부족), PWA만 유지(App Store 배포 불가, iOS 푸시 제약), Android TWA(iOS 해결 안 됨).</li><li><strong>세부 내용</strong>: <a href="/grato-docs/mobile/">iOS·Android 앱</a>. 앱 ID <code>cc.mknw.grato</code>, Capacitor 8.5, iOS는 Swift Package Manager. 로그인 방식은 <a href="#adr-17">ADR-17</a></li></ul><h2 id="adr-9" tabindex="-1">ADR-9 개발 문서는 비공개 저장소의 docs/ → 공개 Pages <a class="header-anchor" href="#adr-9" aria-label="Permalink to &quot;ADR-9 개발 문서는 비공개 저장소의 docs/ → 공개 Pages {#adr-9}&quot;">​</a></h2><ul><li><strong>결정</strong>: 문서는 비공개 소스 저장소의 <code>docs/</code>(VitePress)에 코드와 함께 두고, <code>main</code>에 반영되면 GitHub Actions가 빌드해 공개 저장소 <code>subongjeong/grato-docs</code>의 GitHub Pages로 배포합니다.</li><li><strong>이유</strong>: 문서가 코드 옆에 있어야 같은 커밋에서 함께 고칠 수 있습니다. 소스는 비공개로 두면서 빌드 결과만 공개하면 무료 Pages를 쓰고 외부 협업자·AI 에이전트도 문서를 볼 수 있습니다. 배포 키는 공개 저장소에만 쓰기 권한이 있고, 공개 저장소의 커밋 메시지는 고정 문구로 둡니다.</li><li><strong>대안</strong>: 소스 저장소 자체를 공개(코드·이력 노출), 비공개 저장소 Pages(유료 플랜·접근 제어 필요), 별도 위키·노션(코드와 따로 놀아 갱신 누락).</li><li><strong>주의</strong>: 문서가 공개이므로 비밀값, 관리자 정보, 프로덕션에 반영되지 않은 보안 문제의 세부 내용은 쓰지 않습니다. → <a href="/grato-docs/contributing-docs">문서 작성 규칙</a></li></ul><h2 id="adr-10" tabindex="-1">ADR-10 AI 글쓰기 기능 제거, 질문으로 쓰기로 대체 <a class="header-anchor" href="#adr-10" aria-label="Permalink to &quot;ADR-10 AI 글쓰기 기능 제거, 질문으로 쓰기로 대체 {#adr-10}&quot;">​</a></h2><ul><li><strong>결정</strong>: Gemini로 초안을 만들던 AI 질문 모드를 없애고, 기기 안의 질문 풀로 동작하는 &quot;질문으로 쓰기&quot;로 바꿉니다. 만 14세 이상이 쓰는 서비스로서, 사용자가 쓴 글은 외부 AI 서비스로 보내지 않습니다. <ul><li>질문은 <code>src/content/questions.js</code>의 풀에서 클라이언트가 무작위로 고르고, 답변 1~2개를 빈 줄로 이어 붙여 초안을 만듭니다. 제목은 사용자가 씁니다. → <a href="/grato-docs/features/guided-writing">질문으로 쓰기</a></li><li>이후 질문의 출처는 운영자가 선정한 질문으로 바뀌었습니다(앱 안의 목록은 대체용). 답변과 초안을 기기 안에서 만드는 것은 그대로입니다. → <a href="#adr-11">ADR-11</a></li><li>함수 <code>generateQuestion</code>, <code>generateGratitude</code>와 비밀값 <code>GEMINI_API_KEY</code>, 파라미터 <code>GEMINI_MODEL</code>을 없앱니다.</li><li>컬렉션 <code>aiSessions</code>, <code>aiUsage</code>, <code>aiCache</code>는 규칙에서 클라이언트 접근을 모두 막고(기본 거부), 남은 문서는 <code>purgeAiData</code> 스크립트로 지웁니다. 목적이 끝난 데이터를 보관하지 않기 위해서입니다.</li><li>화면 문구에는 &quot;AI&quot;, &quot;인공지능&quot;을 쓰지 않습니다.</li></ul></li><li><strong>이유</strong>: 외부 생성형 AI로 사용자 글을 보내려면 서비스 대상 연령과 맞는 이용 조건, 별도의 동의와 고지·표시 절차가 따릅니다. 감사 일기는 개인적인 기록이라 이 부담에 비해 얻는 것이 작습니다. 사용자에게 가장 도움이 되던 부분은 &quot;무엇을 쓸지 떠올리게 하는 질문&quot;이었고, 질문은 이미 고정된 풀에서 나오고 있었으므로 모델 없이도 그 가치를 지킬 수 있습니다. 함수 호출·비용·장애 지점도 함께 사라집니다.</li><li><strong>대안</strong>: 동의 화면과 표시를 추가하고 유지(연령 조건과 맞지 않고 출시 절차가 복잡해짐), 다른 AI 제공자로 교체(같은 동의·고지 부담), 기기 내 모델(앱 크기·성능 대비 이득이 작음).</li></ul><h2 id="adr-11" tabindex="-1">ADR-11 질문은 사용자 제안 + 운영자 선정 <a class="header-anchor" href="#adr-11" aria-label="Permalink to &quot;ADR-11 질문은 사용자 제안 + 운영자 선정 {#adr-11}&quot;">​</a></h2><ul><li><strong>결정</strong>: 질문으로 쓰기의 질문은 운영자가 선정한 질문(<code>questions</code>, <code>status == &quot;approved&quot;</code>)에서 고릅니다. 기본 질문은 <code>src/content/questions.json</code>이 원본이고 <code>seedQuestions</code> 스크립트가 Firestore에 넣습니다. 사용자는 질문을 제안할 수 있고(<code>submitQuestion</code>), 운영자(<code>users.isAdmin</code>)만 선정·반려·숨김을 합니다(<code>reviewQuestion</code>). 선정된 사용자 질문에는 제안자의 공개 이름이 함께 보이고, 제안자는 처음 선정될 때 알림을, 선정 수에 따라 배지(1·3·10번)를 받습니다. → <a href="/grato-docs/features/questions">질문 제안과 선정</a></li><li><strong>안전장치</strong>: <ul><li>모든 쓰기는 서버 함수만 합니다(운영자도 클라이언트에서 직접 쓰지 않음).</li><li>제출 때 내용 필터(욕설·혐오 표현, URL, 이메일, 전화번호)와 한도(하루 5개, 하루 시도 30번, 검토 중 20개, 전체 대기 300개), 중복 확인을 적용합니다.</li><li><strong>사전 검토</strong>: 제안한 질문은 운영자가 선정하기 전까지 제안자 본인과 운영자만 봅니다.</li><li>선정된 질문 문서는 로그인한 누구나 읽으므로 공개되면 안 되는 값(운영자 신원, 고치기 전 원문)은 다른 컬렉션에 둡니다.</li><li>선정 때 제안자의 공개 이름이 운영자가 본 이름과 다르면 선정하지 않습니다. 운영자가 확인하지 않은 이름이 질문과 함께 공개되지 않게 하기 위해서입니다.</li></ul></li><li><strong>이유</strong>: 좋은 질문은 사용자에게서 나오고, 자기 질문이 쓰이는 경험은 참여 동기가 됩니다. 하지만 질문은 모든 사용자에게 보이므로 공개 전에 사람이 확인해야 합니다. 질문을 앱 안의 목록에만 두면 앱을 배포해야만 바꿀 수 있어, Firestore로 옮기고 앱 안의 목록은 읽지 못할 때의 대체용으로 남겼습니다.</li><li><strong>대안</strong>: 자동 공개 + 신고(부적절한 질문이 먼저 노출됨), 생성형 모델로 질문 만들기(<a href="#adr-10">ADR-10</a>에서 제외), 앱 안의 목록만 유지(사용자 참여 불가, 수정에 배포 필요).</li></ul><h2 id="adr-12" tabindex="-1">ADR-12 감사는 기본 개인 기록, Circle 공유는 선택 <a class="header-anchor" href="#adr-12" aria-label="Permalink to &quot;ADR-12 감사는 기본 개인 기록, Circle 공유는 선택 {#adr-12}&quot;">​</a></h2><ul><li><strong>결정</strong>: 새 감사 글의 기본 공개 범위는 &quot;나만 보기&quot;(<code>groupId: null</code>)입니다. Circle 공유는 작성 화면에서 &quot;Circle에 공유&quot;와 Circle을 직접 고를 때만 되고, Circle을 미리 선택해 두지 않습니다. 홈 피드의 첫 탭이자 기본 탭은 &quot;내 기록&quot;이고, Circle이 없어도 있습니다. Circle은 계속 비공개이고(목록·검색 없음) 초대 코드로만 참여합니다. → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a></li><li><strong>이유</strong>: 감사 일기는 먼저 자신을 위한 기록입니다. 예전처럼 Circle이 미리 선택되어 있으면 사용자가 의도하지 않게 개인적인 글을 다른 사람에게 보일 수 있습니다. 나누는 것은 분명한 선택이어야 합니다. Circle이 없는 사용자도 홈에서 바로 자기 기록을 볼 수 있어야 합니다.</li><li><strong>영향</strong>: 글을 Circle에 공유해야만 받던 &quot;함께하기&quot;(<code>circle_count</code>) 배지는 이제 Circle을 만들거나 참여할 때 평가합니다.</li><li><strong>대안</strong>: 마지막으로 고른 Circle 기억(같은 실수가 반복됨), 작성 후 공유 전환(글 내용과 <code>groupId</code>를 고칠 수 없는 구조라 변경 규칙이 새로 필요).</li></ul><h2 id="adr-13" tabindex="-1">ADR-13 화면을 막지 않는 시작과 기기 캐시 <a class="header-anchor" href="#adr-13" aria-label="Permalink to &quot;ADR-13 화면을 막지 않는 시작과 기기 캐시 {#adr-13}&quot;">​</a></h2><ul><li><strong>결정</strong>: 앱은 Firebase Auth가 사용자를 알려 주는 즉시 화면을 그립니다. 사용자 프로필은 <code>users/{uid}</code> 실시간 구독으로 받고, 로그인 동기화(이름·태그·사진 정리)는 화면이 뜬 뒤 뒤에서 실행합니다(바뀐 것이 없으면 쓰기 없음). Firestore는 기기 캐시(IndexedDB)를 켜고, 로그아웃 때 이 기기의 캐시를 지웁니다. 페이지는 경로별로 코드를 나누고, Functions·Storage·Messaging 모듈은 처음 쓸 때 받습니다. → <a href="/grato-docs/architecture/client#performance">성능</a></li><li><strong>이유</strong>: 측정해 보니 시작할 때마다 서버 왕복 6~7번(쓰기 포함)을 차례로 기다린 뒤에야 첫 화면이 나왔고, 다시 열어도 캐시가 없어 모두 새로 받았습니다. 느린 휴대폰 조건에서 재방문 첫 화면이 1.6초 → 0.45초로 줄었습니다.</li><li><strong>영향</strong>: 페이지는 프로필을 &quot;아직 모름(<code>undefined</code>)&quot;과 &quot;없음(<code>null</code>)&quot;으로 구분하고, 모르는 동안 뼈대(스켈레톤)를 보여 줍니다. 새 사용자의 첫 글·댓글은 로그인 동기화가 끝날 때까지 기다립니다. 공용 기기 보호를 위해 로그아웃은 캐시를 지운 뒤 페이지를 다시 불러옵니다. 배포로 이전 버전 코드 파일이 사라지면 열려 있던 탭은 한 번 자동으로 새로고침합니다.</li><li><strong>대안</strong>: 동기화를 그대로 두고 로딩 화면만 다듬기(실제 대기 시간은 그대로), 서비스 워커로 앱 전체 캐시(업데이트·무효화 관리 부담이 커서 앱 포팅 때 다시 검토).</li></ul><h2 id="adr-14" tabindex="-1">ADR-14 신고·차단·자동 숨김 <a class="header-anchor" href="#adr-14" aria-label="Permalink to &quot;ADR-14 신고·차단·자동 숨김 {#adr-14}&quot;">​</a></h2><ul><li><strong>결정</strong>: 다른 사람에게 보이는 콘텐츠(Circle 글, 링크 공개 글, 댓글, 공개 이름, Circle 이름)에 네 가지 수단을 둡니다. → <a href="/grato-docs/features/safety">신고·차단과 자동 숨김</a><ul><li><strong>신고</strong>: 사용자가 <code>reports</code>에 직접 만들고(자동 ID, 규칙이 형태 검사), 운영자만 읽습니다. 도배 판단과 대상 정보 복사, 운영자 푸시는 <code>onReportCreated</code>가 합니다.</li><li><strong>차단</strong>: <code>users/{uid}/blocks</code>에 본인이 씁니다. 화면에서 거르는 것은 클라이언트, 알림에서 빼는 것은 서버가 하고, 운영자에게는 낮은 우선순위 신고로 알립니다. 상대에게는 알리지 않습니다.</li><li><strong>자동 숨김(사후 검사 + 즉시 숨김)</strong>: 저장은 막지 않고, 트리거가 욕설·혐오 표현을 찾으면 바로 숨긴 뒤 운영자 대기열에 올립니다. 숨김은 서버만 쓰는 <code>moderation</code> 필드이고, 작성자에게는 &quot;검토 중이에요&quot;로 보입니다. 숨긴 Circle 글은 <code>groupId</code>를 <code>moderation.groupId</code>로 옮겨 Circle 피드 쿼리에서 빠집니다.</li><li><strong>운영자 처리</strong>: <code>moderate</code> callable 하나로 숨기기·해제·삭제·이용 정지·문제 없음을 하고, 같은 대상의 열린 신고를 한꺼번에 닫으며, 작업을 <code>adminAuditLogs</code>에 남깁니다.</li><li>&quot;나만 보기&quot; 글은 대상이 아닙니다. 신고도 검사도 하지 않고, 운영자도 읽을 수 없습니다.</li></ul></li><li><strong>이유</strong>: 스토어는 UGC 앱에 신고·차단·필터와 빠른 대응(약관의 24시간 처리 약속)을 요구합니다. 감사 글은 친구끼리 나누는 짧은 글이라, 저장 전에 막으면 정상 문장이 막히는 불편이 크고(띄어쓰기·합성어 오탐) 우회도 쉽습니다. 저장은 받아 두고 서버가 즉시 숨기면 다른 사람에게 노출되는 시간은 거의 없으면서 작성자의 기록은 사라지지 않습니다. 연락처·링크는 친구에게 쓰는 글에서 자연스러워 자동으로 숨기지 않고 신고에 맡깁니다(질문 제안과 다른 기준). Firestore 쿼리는 &quot;숨김이 아닌 것&quot;을 조건으로 걸 수 없어(필드 없는 예전 문서가 빠짐), 숨긴 글을 Circle 피드에서 빼려면 <code>groupId</code> 자체를 옮겨야 했습니다. 개인 일기는 운영자에게도 보이지 않아야 한다는 원칙(<a href="#adr-12">ADR-12</a>)을 신고 처리에서도 지킵니다.</li><li><strong>대안</strong>: 저장 전에 클라이언트·규칙에서 거절(오탐 불편, 규칙에 단어 목록을 둘 수 없음), 사전 검토(친구 사이의 즉시성을 잃음 — 질문 제안에만 적용, <a href="#adr-11">ADR-11</a>), 숨김을 클라이언트 필터로만 처리(Circle 피드 쿼리에 계속 나옴), 외부 모더레이션 API(사용자 글을 외부로 보내지 않는다는 <a href="#adr-10">ADR-10</a>과 충돌), 차단을 서버 쿼리에 반영(Circle마다 쿼리 조건이 늘고 교차 읽기 한도에 걸림).</li></ul><h2 id="adr-15" tabindex="-1">ADR-15 계정 삭제 범위(삭제 vs 익명화) <a class="header-anchor" href="#adr-15" aria-label="Permalink to &quot;ADR-15 계정 삭제 범위(삭제 vs 익명화) {#adr-15}&quot;">​</a></h2><ul><li><strong>결정</strong>: 계정 삭제(<code>deleteAccount</code>)는 <strong>&quot;내 것은 지우고, 다른 사람에게 이미 의미가 생긴 것은 나와의 연결만 끊는다&quot;</strong> 를 따릅니다. → <a href="/grato-docs/features/account#deletion-scope">계정 삭제</a><ul><li><strong>삭제</strong>: 계정, 프로필, 이름 선점, 내 감사 글과 그 글의 모든 댓글(다른 사람이 쓴 것 포함), 다른 글에 남긴 내 댓글과 리액션, 통계·배지·공유 설정, 푸시 토큰, 의견, 차단 목록, 선정되지 않은 질문 제안과 모든 제안의 원문, 프로필 사진.</li><li><strong>Circle</strong>: 모두 나가고, 관리자였다면 가장 오래 함께한 멤버에게 넘깁니다. 혼자 있던 Circle만 지웁니다. Circle에 쓴 다른 사람의 글은 그대로입니다(<a href="#adr-4">ADR-4</a>).</li><li><strong>익명화</strong>: 선정된 제안 질문(다른 사람이 쓰는 중), 이용 통계 이벤트, 신고 기록(보낸 신고·받은 신고, 처리 후 1년 보관), 운영자 조치 기록.</li><li>삭제 직후 남은 로그인 토큰으로 데이터가 되살아나지 않게 서버 전용 잠금 문서(<code>disabledUsers</code>, 약 2시간)를 먼저 쓰고, Auth 사용자는 마지막에 지웁니다. 최근 10분 안에 로그인한 경우에만 삭제합니다.</li></ul></li><li><strong>이유</strong>: 스토어(Apple 5.1.1(v), Google Play)와 개인정보 보호법은 계정과 개인 데이터의 삭제를 요구하고, 목적을 다한 정보는 지체 없이 파기해야 합니다. 그래서 기본값은 삭제입니다. 다만 선정된 질문은 다른 사용자가 글을 쓰는 데 쓰고 있어, 지우면 남의 기록 흐름이 끊기므로 작성자 정보만 지웁니다. 신고 기록은 재발 방지와 분쟁 대응을 위해 처리방침에 적은 기간만 남기되 누구인지는 지웁니다. Circle을 함께 지우면 다른 멤버의 공간이 사라지므로 넘겨줍니다. 내 글에 달린 남의 댓글은 글이 없으면 맥락이 없고 그 글의 일부로 보아 함께 지웁니다.</li><li><strong>대안</strong>: 모두 삭제(선정된 질문이 사라져 다른 사용자에게 영향, 다른 사람이 보낸 신고의 처리 기록까지 사라져 분쟁 대응과 처리방침의 보관 약속에 맞지 않음), 모두 익명화(글과 댓글은 개인적인 내용이라 익명화로는 개인정보가 남음), 유예 기간 후 삭제(복구 요청 대응은 쉬우나 즉시 삭제 요구와 맞지 않고 예약 작업이 필요 — 출시 후 다시 검토), 삭제를 운영자가 처리(스토어가 앱 안 삭제를 요구).</li></ul><h2 id="adr-16" tabindex="-1">ADR-16 매일 알림: 웹은 15분 단위 서버 푸시, 앱은 휴대폰 자체 알림 <a class="header-anchor" href="#adr-16" aria-label="Permalink to &quot;ADR-16 매일 알림: 웹은 15분 단위 서버 푸시, 앱은 휴대폰 자체 알림 {#adr-16}&quot;">​</a></h2><ul><li><strong>결정</strong>: 웹의 매일 알림은 서버가 15분마다(<code>*/15 * * * *</code>, KST) 그 시각을 고른 사용자에게 푸시를 보내고, 설정 화면도 15분 단위로 고릅니다. iOS·Android 앱에서는 서버 푸시 대신 **휴대폰 자체 알림(로컬 알림)**으로 사용자가 고른 시각에 정확히 띄웁니다(3단계에서 구현). 앱이 로컬 알림을 켠 사용자는 서버 발송 대상에서 빼서 알림이 두 번 가지 않게 합니다.</li><li><strong>이유</strong>: 사용자가 고른 시각에 정확히 오는 것이 핵심입니다. 서버 스케줄러는 실행 간격만큼 오차가 생기고, 예전 설정(<code>every 1 hours</code>)은 매시 40분에 돌아 20시 알림이 20시 40분에 왔습니다. 휴대폰 자체 알림은 분 단위로 정확하고 인터넷 연결이 없어도 옵니다.</li><li><strong>대안</strong>: 서버를 1분마다 실행(호출 수 증가 대비 이점이 작음), 시 단위 유지(사용자 요구와 맞지 않음).</li><li><strong>앱 구현 (3단계)</strong>: 시각은 웹과 같은 15분 단위 설정을 그대로 씁니다. 앞으로 14일 치를 하루씩 예약해 글을 쓴 날은 뺍니다. 예약하는 동안 <code>notificationSettings.dailyReminderChannel = &#39;local&#39;</code>과 <code>dailyReminderLocalAt</code>을 쓰고, 서버는 이 표시가 14일 안이면 그 사용자를 건너뜁니다(웹 브라우저에도 보내지 않아 하루 한 번). 앱을 지워 표시를 되돌리지 못해도 14일 뒤 서버 알림이 다시 갑니다. Android는 정확한 알람 권한을 요청하지 않아(설정 화면으로 보내야 하고 심사 대상) 절전 중에는 몇 분 늦을 수 있습니다. → <a href="/grato-docs/features/notifications#local-reminder">알림: 앱</a></li></ul><h2 id="adr-17" tabindex="-1">ADR-17 앱 로그인은 네이티브 시트 + JS SDK 세션 (<code>skipNativeAuth</code>) <a class="header-anchor" href="#adr-17" aria-label="Permalink to &quot;ADR-17 앱 로그인은 네이티브 시트 + JS SDK 세션 (`skipNativeAuth`) {#adr-17}&quot;">​</a></h2><ul><li><strong>결정</strong>: iOS·Android 앱의 Google·Apple 로그인은 <code>@capacitor-firebase/authentication</code>으로 <strong>플랫폼의 로그인 화면만</strong> 띄우고(<code>skipNativeAuth: true</code>), 받은 ID 토큰으로 웹과 같은 <strong>Firebase JS SDK</strong>에서 <code>signInWithCredential</code>을 합니다. 세션은 JS SDK 하나에만 두고, Firestore·Functions·Storage·규칙은 웹 코드를 그대로 씁니다. 계정 삭제의 재인증도 같은 시트 → <code>reauthenticateWithCredential</code>입니다. → <a href="/grato-docs/mobile/#sign-in">iOS·Android 앱: 로그인</a><ul><li>플러그인은 패키지의 JS 진입점 대신 <code>registerPlugin</code>으로 등록하고, 앱에서만 동적으로 불러옵니다(진입점의 웹 구현이 <code>firebase/auth</code>를 웹사이트 시작 코드에 끌어들임).</li><li>Apple 연결 해제는 iOS에서 네이티브 로그인의 인증 코드를, Android에서 액세스 토큰을 씁니다. JS SDK의 <code>revokeAccessToken</code>은 액세스 토큰만 보내므로 iOS 인증 코드는 Identity Toolkit <code>accounts:revokeToken</code>을 직접 부릅니다.</li><li>로그아웃할 때 네이티브 SDK도 로그아웃합니다(기억된 Google 계정, Android Apple 로그인이 남기는 네이티브 세션).</li></ul></li><li><strong>이유</strong>: Google은 앱 안 웹뷰의 OAuth를 막고(<code>disallowed_useragent</code>), 팝업·리디렉트는 앱의 출처(<code>capacitor://localhost</code>)에서 동작하지 않습니다. 세션을 JS SDK 한 곳에 두면 웹과 같은 uid로 로그인되고, 토큰 갱신·기기 캐시·로그아웃·계정 삭제 흐름과 보안 규칙을 하나도 바꾸지 않아도 됩니다. 한 사람이 웹과 두 앱을 유지하므로 인증 경로가 하나인 것이 가장 중요합니다.</li><li><strong>대안</strong>: 네이티브 Firebase SDK에 로그인하고 JS SDK와 세션을 맞추기(세션이 두 개라 만료·로그아웃·계정 전환이 어긋날 수 있음), 앱 안 브라우저(Safari View Controller·Custom Tabs)로 웹 OAuth 후 커스텀 스킴으로 돌아오기(흐름이 길고 Apple 로그인은 시스템 시트가 기대됨), Google 전용 커뮤니티 플러그인 + Apple 별도 플러그인(플러그인 두 개, 오류 처리 두 벌), Firestore 등까지 네이티브 SDK로 옮기기(웹과 코드가 갈라짐).</li><li><strong>조건</strong>: Firebase에 iOS·Android 앱(<code>cc.mknw.grato</code>)이 등록되어 있어야 하고, Android는 서명 키의 SHA-1·SHA-256을 등록해야 합니다(출시 키는 출시 때). Android의 Apple 로그인은 Firebase Android SDK의 웹 흐름을 쓰므로 Apple Services ID에 Firebase 기본 인증 도메인의 Return URL이 필요합니다.</li></ul><h2 id="adr-18" tabindex="-1">ADR-18 홈 화면 위젯은 숫자·날짜·질문만, 앱이 쓴 요약본으로 <a class="header-anchor" href="#adr-18" aria-label="Permalink to &quot;ADR-18 홈 화면 위젯은 숫자·날짜·질문만, 앱이 쓴 요약본으로 {#adr-18}&quot;">​</a></h2><ul><li><strong>결정</strong>: iOS·Android 홈 화면 위젯(iOS는 잠금 화면 포함)은 연속일, 오늘 기록 여부, 이번 주 기록, 오늘의 질문만 보여 줍니다. 감사 글 내용·이름·Circle은 넣지 않습니다. 앱이 KST 날짜와 숫자로 된 작은 요약본을 위젯 저장소(iOS App Group, Android SharedPreferences)에 쓰고, 위젯은 서버에 접속하지 않고 같은 표시 규칙으로 날짜가 바뀌는 것을 스스로 처리합니다. → <a href="/grato-docs/mobile/#widgets">iOS·Android 앱: 위젯</a></li><li><strong>이유</strong>: 위젯은 휴대폰을 보는 누구에게나 보이고, 감사 글은 기본이 &quot;나만 보기&quot;입니다. 기록 습관을 돕는 데는 숫자와 질문이면 충분합니다. 위젯이 직접 Firestore에 접속하면 인증·규칙·토큰 갱신을 네이티브에서 따로 맞춰야 하고, 요약본 방식이면 오프라인에서도 바로 그려집니다.</li><li><strong>대안</strong>: 지난 감사 글 다시 보기(내용 노출 위험, 필요하면 앱 설정으로 켜는 선택 기능으로 따로 검토), 위젯에서 Firestore 직접 읽기(인증 경로가 하나 더 생김), 서버가 위젯 데이터를 푸시(푸시 권한이 필요하고 늦음).</li></ul><h2 id="adr-19" tabindex="-1">ADR-19 환경 분리: 지금은 로컬 에뮬레이터 + 운영, 출시 뒤 스테이징 <a class="header-anchor" href="#adr-19" aria-label="Permalink to &quot;ADR-19 환경 분리: 지금은 로컬 에뮬레이터 + 운영, 출시 뒤 스테이징 {#adr-19}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 개발과 QA는 기본으로 <strong>로컬 Firebase 에뮬레이터</strong>(가짜 프로젝트 <code>demo-grato</code>)에서 합니다(<code>npm run dev</code>). 실제 프로젝트에 붙는 개발 서버는 <code>npm run dev:prod</code>로 이름을 나눴습니다. 스토어 출시 뒤에는 <strong>스테이징 프로젝트</strong>(<code>grato-stg</code>, <code>stg.grato.today</code>)와 스테이징 앱 빌드(<code>cc.mknw.grato.stg</code>, &quot;Grato β&quot;), GitHub Actions 자동 배포(main 병합 → 스테이징, 승인 → 운영)를 더합니다. → <a href="/grato-docs/guide/getting-started">시작하기: 개발 서버</a></li><li><strong>이유</strong>: Firebase 프로젝트가 운영 하나뿐이라 개발 서버·QA·배포가 모두 실사용자 데이터에 닿았습니다. 1인 운영에서 클라우드 dev·stg·prod 세 벌은 관리 부담이 커서, dev는 에뮬레이터로 대신하고 stg 하나만 둡니다. 운영 데이터는 스테이징으로 복사하지 않습니다(개인정보).</li><li><strong>대안</strong>: 클라우드 dev 프로젝트(설정·비용·로그인 설정이 한 벌 더), 한 프로젝트 안에서 컬렉션 접두어로 나누기(규칙·트리거·인덱스가 섞여 사고 위험).</li></ul><h2 id="adr-20" tabindex="-1">ADR-20 운영 지표는 버튼을 누를 때 서버에서 계산 <a class="header-anchor" href="#adr-20" aria-label="Permalink to &quot;ADR-20 운영 지표는 버튼을 누를 때 서버에서 계산 {#adr-20}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 가입·다시 쓰는 비율·Circle·초대 지표는 운영자가 분석 화면에서 &quot;불러오기&quot;를 누를 때 callable <code>adminMetrics</code>가 Admin SDK로 원본 문서(사용자 전체, 최근 120일 글, Circle, 초대 코드, 초대 이벤트)를 읽어 계산합니다. 결과는 저장하지 않고 개수·비율만 돌려줍니다. 계산은 순수 함수(<code>admin/metricsCalc.ts</code>)로 두어 정의를 테스트로 고정합니다. → <a href="/grato-docs/operations/metrics">운영 지표</a></li><li><strong>이유</strong>: 클라이언트는 규칙상 사용자 목록을 읽을 수 없고, 그렇게 열어서도 안 됩니다. 지금 규모에서는 한 번에 수백~수천 건이라 비용이 작고, 버튼을 누를 때만 읽으면 화면을 열 때마다 읽지 않습니다. 원본에서 바로 세면 정의를 바꿔도 지난 기간까지 다시 계산되고, 집계 문서를 관리할 필요가 없습니다.</li><li><strong>대안</strong>: 스케줄러로 매일 집계 문서 만들기(읽기는 줄지만 정의를 바꾸면 지난 값을 다시 만들어야 함 — 사용자·글이 수만 건으로 늘면 이쪽으로 옮김), BigQuery 내보내기(설정·비용이 큼), 외부 분석 도구(사용자 데이터를 밖으로 보내야 함), 클라이언트에서 계산(규칙상 불가).</li></ul><h2 id="adr-21" tabindex="-1">ADR-21 별명으로 참여하는 공개 Circle &quot;모두의 감사방&quot; <a class="header-anchor" href="#adr-21" aria-label="Permalink to &quot;ADR-21 별명으로 참여하는 공개 Circle &quot;모두의 감사방&quot; {#adr-21}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 운영자가 여는 Circle 하나(<code>groups.kind == &#39;open&#39;</code>, 정원 999명)를 둡니다. 초대 코드 없이 <strong>원하는 사람만</strong> 별명을 정해 참여하고(자동 참여 없음), 그 방의 글·댓글에는 그 방의 별명만 보이고 프로필 사진은 없습니다. 관리자는 운영 전용 계정(&quot;Grato 운영팀&quot;)입니다. → <a href="/grato-docs/features/circles#open-circle">Circle: 모두의 감사방</a>, <a href="/grato-docs/architecture/data-model#open-circle">데이터 모델</a><ul><li><strong>가명이지 익명이 아님</strong>: 글·댓글에는 <code>userId</code>가 그대로 있습니다. 별명은 서버가 쓴 <code>groups/{id}/aliases/{uid}</code>에 있고 규칙이 작성자 필드와 비교합니다. 운영자는 신고된 글의 작성자를 확인할 수 있고, 앱은 이 방에서 작성자의 실제 프로필을 찾아 보여 주지 않습니다(멤버 목록 없음, 차단 목록은 별명으로).</li><li><strong>새 글 알림 없음</strong>, 공감 알림은 공감한 사람의 별명으로.</li><li><strong>멤버 목록은 멤버에게만</strong>: 그룹 문서(<code>memberIds</code>)는 다른 Circle처럼 멤버만 읽습니다. 참여하지 않은 사람의 참여 카드는 설정 스크립트가 <code>appConfig/openCircle</code>에 복사한 이름·설명만 씁니다(관리자가 이름을 고치면 <code>--sync</code>). 앱에는 멤버 목록이 없습니다.</li><li><strong>앱에서 삭제 불가</strong>: 999명이 있는 방이 관리자 계정의 실수 한 번으로 사라지지 않게, <code>deleteCircle</code>과 운영자 화면의 Circle 삭제가 거부하고 설정 스크립트(<code>--delete</code>)로만 지웁니다. 방 자체에 대한 신고에서 &quot;이용 정지&quot;도 거부합니다(관리자가 운영 계정이라 방이 관리자를 잃음). 그 신고는 &quot;문제 없음&quot;으로만 닫고, 문제는 글·댓글·사용자를 대상으로 처리합니다.</li><li><strong>꺼진 채로 배포</strong>: <code>appConfig/openCircle.enabled</code>가 true가 되기 전에는 아무것도 보이지 않고 참여도 거부됩니다. 운영자가 처리방침을 고친 뒤 설정 스크립트로 켭니다. → <a href="/grato-docs/operations/deploy#open-circle">배포: 모두의 감사방 켜기</a></li></ul></li><li><strong>이유</strong>: Circle은 아는 사람끼리 초대 코드로 모이는 곳이라, 함께할 사람이 없는 사용자는 감사를 나눌 곳이 없습니다. 모르는 사람에게 실명과 사진을 보이는 것은 부담이 커서 별명을 씁니다. 완전한 익명은 쓰지 않았습니다. 신고 처리(누가 썼는지 알아야 정지할 수 있음), 차단(사람 단위로 가려야 함), 계정 삭제(내 글을 찾아 지워야 함), 통계·배지가 모두 작성자 uid에 기대고 있고, 만 14세 이상 서비스에서 작성자를 확인할 수 없는 공간은 괴롭힘에 대응할 수 없기 때문입니다. 그래서 다른 멤버에게는 별명만, 운영자에게는 작성자가 보이는 가명으로 했습니다. 참여를 선택으로 한 것은 감사 글이 기본 개인 기록이라는 원칙(<a href="#adr-12">ADR-12</a>)과 같은 이유입니다 — 모르는 사람과 나누는 것은 본인이 고를 때만. 새 글 알림은 999명 방에서는 소음이 되고, 알림에 작성자를 적어야 해서 뺐습니다. 처음에 꺼 두는 것은 운영 계정·처리방침·모니터링을 갖춘 뒤 운영자가 여는 시점을 정하기 위해서입니다.</li><li><strong>알려진 한계</strong>: 멤버라면 누구나 글의 <code>userId</code>로 <code>publicProfiles/{uid}</code>를 get해 별명 뒤의 실제 프로필을 찾을 수 있습니다(규칙이 프로필 get을 로그인 사용자에게 열어 둠, 앱 화면은 하지 않음) — 가명이 감추는 것은 앱에 보이는 이름까지입니다. 차단은 사람(uid) 단위라, 별명으로 차단한 사람이 같은 일반 Circle에 있으면 그곳의 글도 함께 가려지고 일반 Circle 멤버 목록에 &quot;차단됨&quot;이 붙어 누구인지 짐작할 수 있습니다. 나간 사람의 별명은 다른 사람이 다시 쓸 수 있어, 예전 글과 새 글의 별명이 같아도 같은 사람이라는 보장은 없습니다.</li><li><strong>대안</strong>: 완전한 익명(신고·차단·삭제를 처리할 수 없음), 실명 공개 Circle(모르는 사람에게 실명·사진 노출), 모든 사용자를 자동으로 참여(개인 기록 원칙과 충돌, 정원), 별명을 계정 전체의 두 번째 이름으로(다른 Circle과 섞여 관리가 복잡), 초대 코드를 공개로 뿌리기(실명이 보이고 정원 50명).</li></ul><h2 id="adr-22" tabindex="-1">ADR-22 작성자 표시는 지금의 이름·사진·별명을 따름 <a class="header-anchor" href="#adr-22" aria-label="Permalink to &quot;ADR-22 작성자 표시는 지금의 이름·사진·별명을 따름 {#adr-22}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 글·댓글에 복사해 두는 작성자 표시(<code>authorName</code>·<code>authorTag</code>·<code>authorPublicName</code>·<code>authorPhotoURL</code>)를, 이름·사진(<code>publicProfiles</code>)이나 모두의 감사방 별명(<code>aliases</code>)이 바뀌면 <strong>서버가 그 사람의 글·댓글 전부에서 지금 값으로 다시 씁니다</strong>(<code>onPublicProfileUpdated</code>, <code>onOpenCircleAliasUpdated</code> → <code>syncAuthorFields</code>). 모두의 감사방 별명은 7일에 한 번 바꿀 수 있습니다(<code>renameOpenCircleAlias</code>). → <a href="/grato-docs/architecture/cloud-functions#author-sync">작성자 표시 맞추기</a><ul><li>모두의 감사방 글·댓글은 지금 별명(이번 참여 뒤 쓴 것만), 나머지는 지금 프로필. 모두의 감사방에 실제 이름·사진이 들어가는 일은 없습니다.</li><li>이미 있는 글은 1회성 스크립트 <code>backfillAuthorFields</code>로 맞춥니다.</li></ul></li><li><strong>이유</strong>: 이름을 바꾼 사람의 예전 글이 예전 이름으로 남으면 같은 사람이 두 이름으로 보이고, Apple로 가입해 &quot;익명&quot;으로 먼저 쓴 사람은 이름을 정한 뒤에도 첫 글이 &quot;익명&quot;입니다. 사진을 지웠는데 예전 글에 남는 것도 기대와 다릅니다. 별명도 같은 사람이 바꾸기 전과 뒤의 글로 나뉘어 보이면 방에서 대화가 끊깁니다. 피드가 글마다 프로필을 읽게 하면 화면을 열 때마다 읽기가 늘고(ADR-13), 모두의 감사방에서는 실제 프로필을 찾지 않는다는 원칙(ADR-21)과 맞지 않아, 쓰는 쪽(드물게 일어나는 이름 변경)에서 비용을 냅니다. 7일 간격은 별명을 자주 바꿔 방에서 누구인지 흐리거나 여러 별명을 돌려 쓰는 것을 막기 위한 것이고, 참여 직후 오타는 바로 고칠 수 있게 첫 변경은 막지 않습니다.</li><li><strong>알려진 한계</strong>: 이름을 바꿀 때마다 그 사람의 글·댓글을 모두 읽습니다(글이 아주 많은 사람은 그만큼 읽기·쓰기). 이미 보낸 알림, 신고 내용, 차단 목록에 저장한 별명, 선정된 질문의 제안자 이름은 바뀌지 않습니다(질문은 운영자가 선정할 때 본 이름을 지키려는 것, ADR-11). 예전 별명은 바로 풀려 다른 사람이 쓸 수 있고, 나갔다가 다시 참여하면 7일 간격도 처음부터 다시 셉니다.</li><li><strong>대안</strong>: 쓸 때의 이름 그대로 두기(지금까지의 방식), 화면에서 매번 프로필을 읽기(읽기 비용, 모두의 감사방 원칙과 충돌), 별명은 바꿀 수 없게 두기(오타·후회를 나가기로만 해결).</li></ul><h2 id="adr-23" tabindex="-1">ADR-23 배지 보상: 공감 이모지 (서버 지급, 규칙 확인, 원격 켜기) <a class="header-anchor" href="#adr-23" aria-label="Permalink to &quot;ADR-23 배지 보상: 공감 이모지 (서버 지급, 규칙 확인, 원격 켜기) {#adr-23}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 배지를 얻은 사람만 쓰는 공감 이모지를 둡니다(다시 오게 하는 보상). 보상 목록(이모지 ↔ 배지)은 코드에 미리 넣고(앱·서버·규칙 세 곳, 테스트로 같게 유지), <strong>켜기는 <code>appConfig/reactionRewards</code></strong> 로 운영자가 스크립트로 합니다. 서버(<code>evaluateBadges</code>, 스크립트)가 받은 사람의 <code>userBadges.reactions</code>에 넣고, 규칙은 보상 이모지를 더할 때만 그 목록을 읽어 확인합니다. 한 번 받은 보상은 회수하지 않습니다. → <a href="/grato-docs/features/stats-badges#reward-reactions">보상 공감</a></li><li><strong>이유</strong>: 공감은 글 문서의 <code>reactions</code> 맵을 클라이언트가 바로 고치고 규칙이 확인하는 구조라(탭할 때 함수 지연이 없음), 이 구조를 지키면서 &quot;받은 사람만&quot;을 막으려면 규칙이 읽을 수 있는 단순한 목록이 필요합니다. 배지 목록(<code>badges: [{badgeId, earnedAt}]</code>)은 규칙에서 찾기 어려워 서버가 이모지 목록을 따로 씁니다. 켜기를 원격 설정으로 둔 것은 앱 심사 없이 시즌·이벤트에 맞춰 열기 위해서입니다. 이모지를 규칙에 고정한 것은 규칙이 맵을 돌며 검사할 수 없어서입니다.</li><li><strong>알려진 한계</strong>: 새 보상 이모지를 더하려면 규칙·함수 배포와 앱 새 빌드가 필요합니다(켜기만은 원격). 앞으로의 호칭 보상도 같은 방식(서버가 지급 목록을 쓰고 규칙이 확인)으로 붙일 수 있습니다.</li><li><strong>대안</strong>: 공감을 callable로(탭마다 함수 지연), 클라이언트만 막기(규칙 우회 가능), 배지 목록을 규칙에서 직접 검사(구조상 불가).</li></ul><h2 id="adr-24" tabindex="-1">ADR-24 이름 옆 꾸밈: 배지 호칭과 &quot;n일째 감사 중&quot; <a class="header-anchor" href="#adr-24" aria-label="Permalink to &quot;ADR-24 이름 옆 꾸밈: 배지 호칭과 &quot;n일째 감사 중&quot; {#adr-24}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 이름 옆에 (1) 배지로 받은 <strong>호칭</strong> 하나와 (2) 글을 쓴 날의 <strong>연속일</strong>을 보여 줄 수 있게 합니다. 호칭은 배지 문서의 <code>title</code>로 관리자가 달고(시즌·고난도 배지에 달면 시즌·희귀 호칭), 서버가 <code>userBadges.titles</code>에 지급하며, 사용자가 <code>publicProfiles.title</code>로 고릅니다(규칙이 지급받은 것만 허용). 연속일은 사용자가 켜면(<code>users.showStreak</code>) 서버가 새 글에 <code>authorStreak</code>로 찍습니다. 둘 다 모두의 감사방에서도 별명 옆에 보입니다(운영자 결정, 2026-10-17). → <a href="/grato-docs/features/stats-badges#titles">호칭</a>, <a href="/grato-docs/features/stats-badges#show-streak">연속 감사 보여주기</a></li><li><strong>이유</strong>: 매일 쓰는 것과 어려운 배지를 자랑할 수 있게 해 다시 오게 합니다. 호칭은 이름처럼 글에 복사되어(피드가 따로 읽지 않음, ADR-13) 바꾸면 작성자 표시 맞추기(ADR-22)가 지난 글에도 반영합니다. 연속일은 매일 바뀌어 복사본을 맞추기 어렵고 &quot;그날 쓴 기록&quot;이라는 뜻이 자연스러워 글마다 그날 값을 서버가 찍습니다(클라이언트가 꾸밀 수 없음). 호칭 텍스트를 배지 문서에 둔 것은 앱 업데이트 없이 운영자가 시즌 호칭을 만들기 위해서입니다.</li><li><strong>알려진 한계</strong>: 모두의 감사방에서 드문 호칭·긴 연속일은 별명 뒤의 사람을 짐작하게 할 수 있습니다(자랑할 수 있게 하는 쪽을 택함). 1.0.1 이전 앱으로 쓴 글에는 호칭이 빠질 수 있습니다(규칙이 호칭 없는 글을 받아 줌. 다음에 호칭을 바꿀 때 맞춰짐). 받은 호칭은 회수하지 않습니다.</li><li><strong>대안</strong>: 화면에서 작성자 프로필을 매번 읽기(읽기 비용), 연속일을 프로필에 두고 매일 갱신(모든 글 표시가 바뀌어 의미가 흐려짐, 쓰기 비용).</li></ul><h2 id="adr-25" tabindex="-1">ADR-25 프로덕션 배포는 수동 실행 + 오너 승인 CI <a class="header-anchor" href="#adr-25" aria-label="Permalink to &quot;ADR-25 프로덕션 배포는 수동 실행 + 오너 승인 CI {#adr-25}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 웹·함수·규칙 배포를 GitHub Actions 워크플로(<code>deploy.yml</code>)로도 할 수 있게 합니다. 시작은 손으로만(<code>workflow_dispatch</code>, <code>targets</code>), job은 Environment <code>production</code>에서 돌아 <strong>오너가 승인해야</strong> 진행하고, 인증은 Workload Identity Federation(키 파일 없음, 이 저장소의 <code>main</code>·<code>production</code>만)입니다. 함수 배포 전에 배포된 함수와 소스를 비교해 지워질 함수가 있으면 멈춘 뒤에만 <code>--force</code>를 씁니다. → <a href="/grato-docs/operations/deploy#ci">CI로 배포</a></li><li><strong>이유</strong>: 배포가 오너의 맥에서만 가능해 에이전트가 PR 뒤 배포를 준비할 수 없었습니다. 승인 단계로 &quot;프로덕션 배포는 소유자 확인 뒤&quot;를 지키면서, 같은 커밋·같은 순서·같은 검사(테스트, 약관 자리 표시, 함수 삭제)를 매번 기계적으로 돌립니다. <code>--force</code>는 재시도 트리거 때문에 필요하지만 삭제 확인도 건너뛰므로 사람 대신 스크립트가 확인합니다.</li><li><strong>알려진 한계</strong>: 시드·백필·설정 스크립트와 인덱스 준비 확인, 배포 뒤 확인은 여전히 손으로 합니다. 서비스 계정 역할은 처음 실행에서 모자란 권한이 드러날 수 있습니다.</li><li><strong>대안</strong>: main push 때 자동 배포(확인 없이 운영에 나감), 서비스 계정 키 JSON 비밀값(만료 없는 키 유출 위험), 맥에서만 계속 배포(지금 상태).</li></ul><h2 id="adr-26" tabindex="-1">ADR-26 기능 이용 기록은 180일만 보관 (TTL, 기기 시계로 쓰는 만료 시각) <a class="header-anchor" href="#adr-26" aria-label="Permalink to &quot;ADR-26 기능 이용 기록은 180일만 보관 (TTL, 기기 시계로 쓰는 만료 시각) {#adr-26}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: <code>analyticsEvents</code>는 문서마다 <code>expireAt</code>(기록 + 180일)을 넣고 Firestore TTL로 지웁니다. 웹·앱은 기기 시계로 <code>expireAt</code>을 쓰고 규칙은 지금부터 190일 안쪽만 받습니다(선택 필드). 서버가 쓰는 <code>badge_earned</code>도 같은 180일. 쿼리에 쓰지 않는 <code>props</code>·<code>platform</code>·<code>expireAt</code>은 단일 필드 인덱스에서 뺍니다. 예전 문서는 <code>backfillAnalyticsExpireAt</code>으로 채웁니다. → <a href="/grato-docs/operations/deploy#analytics-ttl">보관 기간 켜기</a></li><li><strong>이유</strong>: 원본 이벤트가 무기한 쌓이면 저장·색인 비용이 늘고, 개인정보도 필요 이상으로 오래 남습니다. 지표는 최근 30일(초대)과 오늘(오늘 현황)만 원본을 읽어 180일이면 넉넉합니다. Firestore에는 &quot;서버 시간 + n일&quot; 값이 없어 클라이언트가 계산하고, 기기 시계 오차를 10일까지 받아 줍니다.</li><li><strong>알려진 한계</strong>: 예전 앱 빌드는 <code>expireAt</code> 없이 기록하므로, 새 앱 빌드가 퍼질 때까지 백필을 다시 돌려야 합니다. 기기 시계가 10일 넘게 앞서거나 크게 뒤처지면 그 이벤트는 저장되지 않습니다(분석 기록이라 화면에는 영향 없음). TTL 삭제는 만료 뒤 보통 하루 안쪽입니다.</li><li><strong>대안</strong>: 생성 트리거가 <code>expireAt</code>을 찍기(이벤트마다 함수 호출 비용), 예약 함수로 오래된 문서 지우기(읽기·삭제 비용, 코드 유지), <code>expireAt</code>을 필수로(예전 앱의 기록이 모두 거부됨).</li></ul><h2 id="adr-27" tabindex="-1">ADR-27 가입 유입 경로는 가입한 사람만, 가입할 때 한 번 <a class="header-anchor" href="#adr-27" aria-label="Permalink to &quot;ADR-27 가입 유입 경로는 가입한 사람만, 가입할 때 한 번 {#adr-27}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 웹에서 처음 누른 캠페인 링크(UTM)를 기기에 30일 보관했다가, 그 기기에서 새 계정을 만들 때만 <code>users.signupSource</code>로 한 번 남기고 지웁니다. UTM 없는 초대 링크는 <code>invite</code>. 규칙은 생성 때만 정해진 형식을 받고 그 뒤 변경을 거부합니다. 앱에서는 모으지 않고, 앱 설치는 App Store 캠페인 링크로 봅니다. 처리방침 개정 시행일 전에는 기기에도 남기지 않습니다(<code>SIGNUP_SOURCE_FROM</code>). → <a href="/grato-docs/operations/metrics#signup-sources">유입 경로</a></li><li><strong>이유</strong>: 출시 캠페인의 게시처별 가입과 첫 글을 비교해야 합니다. 방문 기록을 서버에 남기지 않으면(가입한 사람의 것만, 짧은 표시만, 주소·리퍼러·시각 없음) 외부 분석 도구나 광고 식별자 없이도 채널을 비교할 수 있고, 처리방침에 적을 항목도 작습니다. 처음 누른 링크를 셈해 &quot;처음 알게 된 곳&quot;을 봅니다. 규칙이 생성 때만 받는 것은 기존 계정이 나중에 값을 끼워 넣어 표를 흐리지 않게 하기 위해서입니다.</li><li><strong>알려진 한계</strong>: 기기가 보내는 값이라 꾸밀 수 있어 통계로만 씁니다(보상 근거 아님). 다른 기기·앱에서 가입하면 잡히지 않습니다. Circle callable이 <code>users</code> 문서를 먼저 만든 드문 경우에는 남지 않습니다. 저장이 막힌 브라우저는 남지 않습니다.</li><li><strong>대안</strong>: 방문 이벤트를 모두 서버에 기록(가입하지 않은 사람까지 남음), 외부 분석 SDK(데이터가 밖으로 나감), 마지막 링크 기준(재방문 채널이 앞 채널을 덮음).</li></ul><h2 id="adr-28" tabindex="-1">ADR-28 끊김 직후 복구 &quot;쉼표의 날&quot;과 기록한 날 먼저 보여 주기 <a class="header-anchor" href="#adr-28" aria-label="Permalink to &quot;ADR-28 끊김 직후 복구 &quot;쉼표의 날&quot;과 기록한 날 먼저 보여 주기 {#adr-28}&quot;">​</a></h2><ul><li><strong>결정 (2026-10, GRATO-21)</strong>: (1) 연속일이 끊긴 <strong>다음 날 하루 안에</strong> 글을 쓰면 비운 하루를 &quot;쉼표의 날&quot;로 바꿔 연속일을 잇습니다. 따로 누르는 버튼 없이 <strong>서버가 글을 셀 때</strong> 정하고(<code>computeNextStats</code>, <code>userStats.restDays</code>), 조건은 비운 날이 딱 하루·그 전 연속일 3일 이상·그 달 1번(<code>streakRest.json</code>의 <code>minStreak</code>·<code>perMonth</code>). 쉼표의 날은 연속일 수에 더하지 않습니다. 유료 판매·미리 쌓는 보호권은 없습니다. (2) 홈 카드는 <strong>기록한 날(누적, <code>userStats.activeDays</code>)을 먼저</strong>, 연속일은 3일째부터 작은 칩으로만 보여 주고, 끊긴 연속일을 &quot;0&quot;으로 보여 주지 않으며 문구는 바깥 사정 탓(&quot;바쁜 하루였나 봐요&quot;)으로 씁니다. 마이페이지 숫자 칸도 기록한 날이 먼저입니다. (3) 설정에 <strong>연속일 숨기기</strong>(<code>users.hideStreak</code>)를 둡니다. → <a href="/grato-docs/features/stats-badges#rest-day">쉼표의 날</a>, <a href="/grato-docs/features/stats-badges#hide-streak">연속일 숨기기</a></li><li><strong>이유</strong>: 끊긴 연속 기록이 화면에 보이기만 해도 이후 참여가 줄고, 끊김을 자기 탓으로 돌릴수록 크게 줄며, 복구할 수 있으면 덜 줄었습니다(Silverman &amp; Barasch 2023). 실패 <strong>직후</strong> 쓰는 여유분이 재시도율을 가장 많이 올렸고, 미리 준 여유분은 효과가 작았습니다(Sharif &amp; Shu: 84.7%·78.2% 대 54.7%). 그래서 미리 주는 보호권 대신 끊긴 다음 날에만 열리는 복구를 골랐습니다. 그중 &quot;다음 날 쓰면 이어짐&quot;은 사용자가 할 일이 평소와 같아(글 하나) 가장 단순하고, 서버가 글을 셀 때 판단하므로 클라이언트가 조작할 수 없습니다(ADR-7). 연속일 3일 이상은 연구의 연속 기록 정의(3회 이상)와 &quot;3일째부터 강조&quot;에 맞췄고, 짧은 연속일에 한도를 써 버리지 않게 합니다. 월 한 번은 &quot;가끔 쉬어도 된다&quot;와 &quot;그래도 연속일은 연속일&quot;의 균형으로 잡은 가정입니다. 기록한 날은 끊겨도 줄지 않는 진척이라 근거 보고서가 주 지표로 권한 값입니다.</li><li><strong>재계산과의 관계</strong>: 글을 지워 <code>rebuildUserStats</code>가 다시 계산할 때 <code>restDays</code>는 그대로 두고, 양쪽 날에 글이 있으면 계속 이어 줍니다(복구가 사라지지 않음). 이미 쉼표의 날인 날을 다시 이을 때는 한도를 다시 쓰지 않습니다. <code>activeDays</code>는 남은 글의 날짜 수로 다시 셉니다. 연속 배지와 &quot;n일째 감사 중&quot;은 이어진 연속일을 그대로 씁니다.</li><li><strong>알려진 한계</strong>: 쉼표의 날을 미리 알리는 것은 홈 카드 문구뿐입니다(알림·위젯 문구 없음). 마이페이지 캘린더의 &quot;이번 달 최장 연속&quot;은 그 달 글 날짜만 보므로 쉼표의 날을 잇지 않습니다. 예전 <code>userStats</code>에는 <code>activeDays</code>가 없어 백필(<code>backfillActiveDays</code>) 전까지 &quot;나의 감사 기록&quot;으로 보입니다. 순서가 뒤바뀐 오래된 글은 <code>activeDays</code>를 올리지 않습니다(다음 재계산이 맞춤).</li><li><strong>대안</strong>: ① 끊긴 다음 날 &quot;쉼표의 날로 바꾸기&quot; 버튼(callable) — 선택권은 있지만 함수·화면이 늘고 누르지 않으면 효과가 없음. ② &quot;오늘 2개 쓰면 이어 붙이기&quot; — 근거 보고서의 예시지만 하루 두 번 쓰기 압박과 짧은 글 쪼개기를 부름. ③ 미리 쌓는 보호권(Duolingo식) — 미리 준 여유분은 효과가 작고 손실 회피를 키움. ④ 연속일 표시를 아예 없애기 — 연속일을 좋아하는 사용자와 연속 배지를 버림. ⑤ 기록한 날을 화면에서만 계산 — 전체 글을 읽어야 해 시작 경로가 무거워짐(ADR-13).</li></ul><h2 id="adr-29" tabindex="-1">ADR-29 배지 축하는 계정에 남기는 &quot;본 배지&quot; 시각 하나로 한 번만 <a class="header-anchor" href="#adr-29" aria-label="Permalink to &quot;ADR-29 배지 축하는 계정에 남기는 &quot;본 배지&quot; 시각 하나로 한 번만 {#adr-29}&quot;">​</a></h2><ul><li><strong>결정 (2026-10, GRATO-18·19·20)</strong>: 축하한 배지는 배지 목록이 아니라 <strong>시각 하나</strong>로 기록합니다. <code>users/{uid}.badgesSeenAt</code> = 축하한(또는 기준선으로 정한) 배지 중 가장 늦은 <code>earnedAt</code>. 이보다 늦게 받은 배지만 새 배지로 보고, 둘 이상이면 한 장으로 묶습니다. 카드가 <strong>열리는 순간</strong> 기기(<code>localStorage</code>)와 계정에 함께 적고, 띄우기 전에 서버에서 한 번 더 읽습니다. 값이 없는 계정은 처음 볼 때 기준선을 정합니다: 만든 지 24시간이 넘었으면 지금 가진 배지 중 가장 늦은 시각(업데이트 뒤 쏟아지지 않음), 그 안이면 0. 규칙은 timestamp·미래 금지·앞으로만. &quot;다음 배지까지 n&quot;에 필요한 서버 집계 숫자는 <code>evaluateBadges</code>가 <code>userBadges.progress</code>에 함께 저장합니다. → <a href="/grato-docs/features/stats-badges#celebration">배지 축하</a>, <a href="/grato-docs/features/stats-badges#next-badge">다음 배지</a></li><li><strong>이유</strong>: 티켓이 &quot;다른 기기에서 다시 안 뜸&quot;을 요구하므로 기기 저장만으로는 안 되고 계정에 남겨야 합니다. 시각 하나는 배지가 늘어도 크기가 그대로이고, 규칙으로 &quot;앞으로만&quot;을 지키기 쉬우며, 동시에 받은 배지 묶음과도 맞습니다(같은 트랜잭션의 배지는 <code>earnedAt</code>이 같음). 클라이언트가 쓰는 값이지만 꾸며도 자기 화면의 축하만 바뀌므로 서버 전용으로 둘 이유가 없습니다. <code>userBadges</code>는 서버 전용으로 남깁니다. 열 때 기록하는 것은 &quot;한 번 이상 귀찮게 하지 않게&quot; 하기 위해서입니다(닫기 전에 앱을 꺼도 다시 뜨지 않음).</li><li><strong>알려진 한계</strong>: 기준선은 출시 날짜가 아니라 &quot;그 계정이 새 앱으로 처음 열린 때&quot;라서, 예전 앱으로 받은 배지는 업데이트 뒤 축하하지 않습니다. 만든 지 24시간이 안 된 계정이 예전 앱에서 받은 첫 배지는 업데이트 뒤 한 번 축하합니다. 계정에 쓰지 못하고 기기 저장도 막힌 브라우저에서는 같은 배지가 다른 기기에서 한 번 더 뜰 수 있습니다. <code>earnedAt</code>은 함수가 같은 <code>userBadges</code> 문서 트랜잭션 안에서 찍는 서버 시각이라 커밋 순서와 거의 같지만, 함수 인스턴스 사이 시계 차이(밀리초)로 거의 같은 순간에 받은 배지 하나가 축하에서 빠질 이론적 가능성은 남습니다(배지는 그대로 받음).</li><li><strong>대안</strong>: ① 축하한 배지 ID 목록(<code>celebratedBadgeIds</code>) — 정확하지만 배지 수만큼 커지고 규칙으로 &quot;추가만&quot;을 확인하기 번거로움. ② 서버가 <code>userBadges</code>에 <code>celebrated</code> 표시 + callable — 함수 호출이 늘고 콜드 스타트 동안 다시 뜰 수 있음. ③ 기기 저장만 — 다른 기기에서 다시 뜸(티켓 조건 위반). ④ 고정 출시 날짜를 기준선으로 — 날짜를 코드에 박아야 하고 배포가 늦으면 그 사이 배지가 쏟아짐.</li></ul><h2 id="adr-30" tabindex="-1">ADR-30 모두의 감사방 광고 검사: 숨기지 않고 운영자 대기열에만 <a class="header-anchor" href="#adr-30" aria-label="Permalink to &quot;ADR-30 모두의 감사방 광고 검사: 숨기지 않고 운영자 대기열에만 {#adr-30}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 모두의 감사방의 글·댓글만 링크·이메일·전화번호와 돌려 쓴 연락처(한글로 쓴 번호 &quot;공일공…&quot;, 메신저 ID 안내 &quot;카톡 아이디 …&quot;, <code>naver[.]com</code> 같은 링크)를 서버가 찾아 <strong>운영자 대기열에만</strong> 올립니다. 자동으로 숨기지 않고, 작성자에게 알리지 않습니다. 신고는 사유 <code>spam</code>, <code>source: &quot;ad&quot;</code>, 걸린 <strong>징후 이름</strong>(<code>signals</code>)만 남기고 글 원문·발췌는 복사하지 않습니다. 같은 대상에는 정해진 ID(<code>ad_…</code>)로 한 번만 올립니다. 검사는 두 가지입니다: 글·댓글이 저장될 때 그 글 하나를 보는 검사와, 6시간마다 여러 글에 걸친 패턴(같은 링크 반복, 몰아쓰기, 갓 들어온 계정)을 보는 예약 검사. 운영자 화면에는 &quot;광고 의심&quot; 모아 보기를 둡니다. → <a href="/grato-docs/features/safety#ad-check">광고 검사</a></li><li><strong>이유</strong>: 모두의 감사방은 별명으로 누구나 들어오는 곳이라 광고가 들어오기 가장 쉽고, 친구끼리의 Circle과 달리 링크가 정상인 경우가 드뭅니다. 그래도 링크·숫자만으로 판단하면 정상 글(책 링크, 기념일 숫자)도 걸리므로 숨기는 결정은 사람에게 둡니다. 원문을 복사하지 않는 것은 대상 글에서 바로 읽을 수 있고, 작성자가 지우면 원문도 함께 사라지게 하기 위해서입니다. 쓸 때 검사를 함께 두는 것은 6시간 주기만으로는 링크 하나 달린 광고도 최대 6시간 뒤에야 보이기 때문입니다.</li><li><strong>알려진 한계</strong>: 공감은 누가 언제 했는지 시각이 없어 &quot;1시간에 공감 30개&quot; 징후는 아직 보지 않습니다. 6시간 검사는 실행마다 최대 글 1,000개·댓글 3,000개를 읽습니다. 돌려 쓴 표기는 끝이 없어 일부만 잡습니다(한글 숫자는 3글자 이상이 섞인 8자리 이상, 메신저 이름 뒤에 아이디·콜론·@·&quot;문의/친추/검색/DM&quot;이 올 때). 일반 Circle과 링크 공개 글은 지금처럼 신고에만 맡깁니다. 작성자가 글을 지우면 신고에는 징후 이름만 남습니다.</li><li><strong>대안</strong>: 링크가 든 글을 바로 숨기기(정상 글까지 가림, 오탐을 작성자가 겪음), 모든 Circle에 적용(친구끼리 나누는 링크는 정상), 신고에 원문 복사(지운 뒤에도 남는 개인정보), 질문 필터처럼 저장 거절(별명 방에서 우회만 부추김).</li></ul><h2 id="adr-31" tabindex="-1">ADR-31 모두의 감사방 오늘의 주제: 서버만 쓰는 주제 문서, 답은 감사 글 <a class="header-anchor" href="#adr-31" aria-label="Permalink to &quot;ADR-31 모두의 감사방 오늘의 주제: 서버만 쓰는 주제 문서, 답은 감사 글 {#adr-31}&quot;">​</a></h2><ul><li><strong>결정 (2026-10, GRATO-22)</strong>: 모두의 감사방 맨 위에 매일 07:00(KST) 주제 하나를 올립니다. 주제는 <strong>운영 계정의 글이 아니라 서버만 쓰는 별도 문서</strong> <code>dailyTopics/{YYYY-MM-DD}</code>이고(운영자 callable <code>manageDailyTopic</code> + <code>adminAuditLogs</code>, 예약 게시는 <code>publishAt</code>과 규칙으로), 답은 <strong>일반 감사 글</strong>에 <code>topicId</code>·<code>topicText</code>를 붙여 저장합니다. 답은 개인 글이거나 모두의 감사방 글이고, 규칙이 주제가 올라갔는지와 문구가 같은지 확인합니다. 화면은 &quot;오늘 n명이 답했어요&quot;(사람 수, 3명 미만이면 숫자 없음)만 보이고 시간순(새 답이 위)이며, 내가 답하기 전에는 새 답 3개만 보입니다(나만 보기 답도 인정). 답의 공감 숫자는 작성자에게만 보입니다. 운영 규칙은 오너가 확정한 운영 안(GRATO-3)을 따릅니다. → <a href="/grato-docs/features/circles#daily-topic">오늘의 주제</a>, <a href="/grato-docs/architecture/data-model#daily-topics">데이터 모델</a></li><li><strong>이유</strong>: 주제를 운영 계정의 글로 두면 예약 게시를 할 수 없고(07:00에 사람이 올려야 함), 운영 계정이 방에 글을 쓰는 첫 사례가 되어 &quot;운영 계정은 답하거나 공감하지 않는다&quot;는 원칙과 섞이며, 답이 그 글의 댓글이 되어 기록한 날·배지에 쌓이지 않습니다. 별도 문서는 결·출처(선정 질문, 시즌)·예약 시각을 담을 수 있고, 시즌 질문(GRATO-66)도 <code>source: &#39;season&#39;</code>, <code>seasonKey</code>로 같은 구조에 들어옵니다. 답을 감사 글로 두면 통계·배지·신고·차단·삭제·별명 규칙을 새로 만들 필요가 없고(답 쓰기는 기존 생성 경로 그대로: 동의·활성 계정·별명), 나만 보기로 답해도 개인 기록으로 남습니다(<a href="#adr-12">ADR-12</a>). 주제 문구를 답에 복사해 두는 것은 내 기록·지난 답에서 무엇에 답했는지 보이게 하면서 화면마다 주제를 다시 읽지 않기 위해서이고(ADR-13), 규칙이 지금 문구와 비교해 운영자가 쓰지 않은 말을 주제처럼 붙이는 것을 막습니다. 숫자를 사람 수 하나로, 정렬을 시간순으로, 다른 사람 답의 공감 숫자를 숨긴 것은 비교를 줄이기 위해서입니다(GRATO-3 5장). 선정 질문의 제안자 이름을 방에 보이지 않는 것은 별명만 보이는 방의 약속 때문입니다(<a href="#adr-21">ADR-21</a>).</li><li><strong>알려진 한계</strong>: &quot;답하면 펼쳐짐&quot;은 화면의 안내일 뿐이라, 멤버는 피드 쿼리로 모든 답을 읽을 수 있습니다(규칙을 바꾸지 않음). &quot;n명&quot;은 카드가 읽는 최근 200개 답에서 셉니다. 운영자가 올라간 주제의 문구를 고치면 그 전의 답은 예전 문구를 지니고, 고친 순간 쓰던 사람의 저장은 한 번 거부된 뒤 앱이 다시 읽어 저장합니다. 1.0.1 이하 앱에는 주제 카드가 없고 답이 보통 글처럼 보입니다. 선정 질문이 주제로 쓰일 때의 제안자 배지·알림은 GRATO-29에서 <code>questionId</code>로 이어 받습니다.</li><li><strong>대안</strong>: 운영 계정의 고정 글 + 댓글로 답하기(예약 불가, 기록·배지에 안 쌓임), 답을 새 컬렉션으로(통계·신고·삭제 경로를 새로 만들어야 함), 주제 문구를 답에 넣지 않고 화면에서 매번 읽기(읽기 비용, 내 기록에서도 주제를 찾아야 함), 규칙으로 답 목록 잠그기(Firestore 쿼리로 &quot;내가 답했는지&quot;를 확인할 수 없고, 잠금이 목적이 아님), 서버 카운터로 &quot;n명&quot;(차단한 사람을 뺄 수 없음).</li></ul><h2 id="adr-32" tabindex="-1">ADR-32 댓글 공감: 기본 4종, 작은 숫자, 알림 없음 <a class="header-anchor" href="#adr-32" aria-label="Permalink to &quot;ADR-32 댓글 공감: 기본 4종, 작은 숫자, 알림 없음 {#adr-32}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 댓글에도 공감을 답니다. 댓글 문서의 <code>reactions</code> 맵(<code>{ 이모지: uid[] }</code>, 첫 공감 전에는 없음)을 글 공감과 같은 모양으로 클라이언트가 바로 고치고, 규칙이 확인합니다: 바뀌는 필드는 <code>reactions</code>뿐, <strong>기본 4종(❤️ 🙏 ✨ 🔥)만</strong>, 키마다 자기 uid만 더하거나 빼고, 부모 글을 읽을 수 있는 사람만, 숨긴 댓글에는 불가, 활성 계정만(<code>isActiveUser</code>). 화면은 작은 칩에 작은 숫자, 댓글은 언제나 오래된 순. 차단한 사람의 공감은 숫자에서 뺍니다. <strong>댓글 공감 알림은 보내지 않습니다.</strong> 계정 삭제는 다른 사람 댓글에 남긴 공감도 지웁니다(컬렉션 그룹 인덱스 <code>comments.reactions</code>). → <a href="/grato-docs/features/gratitudes#comment-reactions">댓글 공감</a>, <a href="/grato-docs/architecture/security-rules#comment-reactions">규칙</a></li><li><strong>이유</strong>: 댓글에 &quot;잘 읽었어요&quot;를 남길 가벼운 방법이 없어 짧은 댓글이나 무응답이 됩니다. 공감은 서로를 비교하는 숫자가 되기 쉬워, 숫자를 작게 두고 공감 수로 정렬하거나 강조하지 않습니다(감사는 경쟁이 아님). 보상 공감(ADR-23)은 글에만 둡니다: 배지 보상의 의미를 글 공감에 모으고, 댓글 규칙이 <code>userBadges</code>를 읽지 않아 교차 읽기가 늘지 않으며, 목록이 네 곳(앱·함수·규칙 두 곳)으로 퍼지지 않습니다. 알림은 글 공감 알림(<code>onReactionUpdated</code>)과 같은 방식으로 붙일 수 있지만, 댓글마다 알림이 생겨 알림 수가 늘어나므로 오너가 정할 때까지 보내지 않습니다(서버 트리거 없음). 잠금 확인은 글 공감에는 없지만, 공감은 다른 사람 문서에 내 uid를 쓰는 일이라 계정 삭제 직후 남은 토큰으로 되살아나지 않게 붙였습니다.</li><li><strong>알려진 한계</strong>: 누가 눌렀는지는 보여 주지 않습니다(모두의 감사방에서도 프로필을 읽지 않음). 다만 규칙상 댓글을 읽는 사람은 uid 목록을 볼 수 있습니다(글 공감과 같음). 규칙은 차단을 보지 않아, 차단한 사람도 내 댓글에 공감할 수 있고 내 화면에서만 빠집니다. 예전 앱 빌드에는 댓글 공감이 보이지 않습니다.</li><li><strong>대안</strong>: 공감 수를 아예 숨기기(내가 눌렀는지만 표시 — 오너가 고를 수 있음), 보상 공감도 허용(규칙 읽기 1번 더, 목록 동기화), 공감을 하위 컬렉션 문서로(쓰기·읽기 비용, 목록 쿼리 필요), callable로(탭마다 함수 지연).</li></ul><h2 id="adr-33" tabindex="-1">ADR-33 글마다 정해진 시각의 일회성 작업은 Cloud Tasks <a class="header-anchor" href="#adr-33" aria-label="Permalink to &quot;ADR-33 글마다 정해진 시각의 일회성 작업은 Cloud Tasks {#adr-33}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: &quot;이 글이 만들어지고 24시간 뒤에 한 번&quot; 같은 일은 Cloud Tasks 작업 큐 함수(<code>onTaskDispatched</code>)로 합니다. 첫 사용은 첫 나눔 리더 알림 <code>firstShareFollowup</code>(GRATO-77). 작업은 만든 쪽(트리거)이 Admin SDK로 넣고, 작업 ID를 대상 문서에서 정해(<code>first_followup_{gratitudeId}</code>) 중복을 막습니다. 실행은 결과를 먼저 기록한 뒤 보내는 방식(많아야 한 번)입니다. → <a href="/grato-docs/architecture/cloud-functions#first-share-followup">Cloud Functions</a></li><li><strong>이유</strong>: 정해진 주기로 전체를 훑는 스케줄러와 달리, 일이 있는 글에만 정확한 시각에 한 번 돕니다(읽기 비용이 글 수에 비례). Cloud Scheduler 작업(무료 3개 중 사용 중)을 늘리지 않습니다. 재시도·동시 실행 제한을 큐가 맡습니다.</li><li><strong>알려진 한계</strong>: 새 함수 종류라 Cloud Tasks API와 IAM 역할(실행 계정 <code>roles/cloudtasks.enqueuer</code>·자기 자신에 대한 <code>roles/iam.serviceAccountUser</code>, 배포 계정 <code>roles/cloudtasks.queueAdmin</code>)이 처음 한 번 필요합니다 → <a href="/grato-docs/operations/deploy#cloud-tasks">배포: Cloud Tasks</a>. 함수를 지우면 이미 넣은 작업은 실행 시 실패합니다(재시도 뒤 버려짐). 에뮬레이터는 예약 시각을 그대로 지키지 않을 수 있어 시각은 단위 테스트로 확인합니다.</li><li><strong>대안</strong>: 15분 스케줄러가 24시간 지난 첫 나눔을 찾기(스케줄러 작업 하나 더, 시각이 15분 단위로 어긋남, 인덱스 필요), 반응 트리거에서 처리(반응이 없을 때가 대상이라 맞지 않음), 클라이언트 로컬 알림(리더 기기에 미리 알 방법이 없음).</li></ul><h2 id="adr-34" tabindex="-1">ADR-34 가입 직후 &quot;언제 감사를 떠올릴까요?&quot; 한 화면 (실행 의도) <a class="header-anchor" href="#adr-34" aria-label="Permalink to &quot;ADR-34 가입 직후 &quot;언제 감사를 떠올릴까요?&quot; 한 화면 (실행 의도) {#adr-34}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 새 계정은 동의를 마친 뒤 한 화면에서 감사를 떠올릴 때(정해진 6가지 + 시각)를 고르고, 그 시각을 매일 알림 시각으로 씁니다. <code>users.writingPlan = { cue, hour, minute, setAt }</code>. 건너뛸 수 있고, 알림 권한은 주 버튼을 누를 때만 묻습니다. 초대 링크로 온 사람은 초대를 먼저 끝내고, 계획이 없는 계정(기능 전 가입 포함)은 홈 카드로 한 번 묻습니다. → <a href="/grato-docs/features/account#writing-plan">가입 직후</a></li><li><strong>이유</strong>: &quot;언제·어디서 할지&quot;를 if–then으로 정하는 실행 의도는 행동 시작에 효과가 큰 단일 기법입니다(메타 분석 d = .65). 가입 직후가 가장 동기가 높고, 고른 때를 알림 시각으로 이으면 단서가 매일 다시 옵니다. 자유 글 대신 정해진 목록이라 내용 검사·개인 정보가 늘지 않습니다.</li><li><strong>지키는 것</strong>: 시작을 막지 않음(<a href="#adr-13">ADR-13</a>) — 지연 로딩, 저장은 뒤에서, 실패해도 다음 화면. 앱의 매일 알림은 그대로 로컬 알림(<a href="#adr-16">ADR-16</a>). 정한 때에 쓰지 않았다고 따로 알리지 않습니다.</li><li><strong>알려진 한계</strong>: 홈 카드를 닫은 기록은 기기별(<code>localStorage</code>)이라 다른 기기에서 한 번 더 보일 수 있습니다. 설정에서 알림 시각만 바꾸면 계획의 시각과 달라질 수 있습니다.</li><li><strong>대안</strong>: 동의 화면에 선택지를 넣기(약관 동의와 섞여 거절하기 어려워짐), 첫 글을 쓴 뒤 묻기(첫 글을 쓰지 않는 사람에게 닿지 않음), 자유 입력(&quot;어디서&quot;까지 글로) — 내용 검사 대상이 늘어 뺌.</li></ul><h2 id="adr-35" tabindex="-1">ADR-35 시즌 질문은 앱의 날짜 계산 + 앱 안 사본, 시드는 &quot;다른 질문&quot;과 예전 앱용 <a class="header-anchor" href="#adr-35" aria-label="Permalink to &quot;ADR-35 시즌 질문은 앱의 날짜 계산 + 앱 안 사본, 시드는 &quot;다른 질문&quot;과 예전 앱용 {#adr-35}&quot;">​</a></h2><ul><li><strong>결정 (2026-10, GRATO-72)</strong>: 연말연초 시즌의 그날 질문은 앱이 KST 날짜로 정합니다(<code>questions.json</code>의 <code>seasons</code>, <code>seasonQuestions.js</code>). 쓰기 화면 카드·위젯·카드뉴스가 같은 함수를 쓰고, 앱 안 사본이 있어 시드 전이나 읽기 실패에도 나옵니다. 시즌 질문은 <code>seedSeasonQuestions</code>로 <code>system_season_*</code> 선정 질문으로도 넣어 &quot;다른 질문&quot;과 예전 앱의 풀에 들어가게 하고, 시즌이 끝나면 숨깁니다. 기본 순환에서는 시즌 질문을 빼서 시드해도 순서가 밀리지 않습니다. 운영자가 숨긴 시즌 질문은 &quot;그 시즌의 다른 질문은 풀에 있는데 이것만 없음&quot;으로 알아보고 그날은 기본 순환으로 돌립니다. 매일 알림 문구도 같은 날짜로 시즌판(문구는 서버·앱 JSON 두 사본, 테스트로 같게). → <a href="/grato-docs/features/guided-writing#season-questions">시즌 질문</a></li><li><strong>이유</strong>: 날마다 바꾸는 서버 스케줄러가 필요 없고(날짜 계산으로 충분), 앱이 오프라인이어도 위젯 7일 치·로컬 알림 14일 치가 맞습니다. 순환 순서가 그대로라 시즌 밖 사용자 경험과 카드뉴스 순서가 흔들리지 않습니다.</li><li><strong>알려진 한계</strong>: 사용자는 숨긴 문서를 읽을 수 없어 &quot;시드 전&quot;과 &quot;모두 숨김&quot;을 구별하지 못합니다. 시즌 질문을 모두 숨기면 iOS 1.0.1 (5) 이상 앱은 앱 안 사본을 보입니다(한 날만 숨기는 것은 됨). 시즌 날짜·문구를 바꾸려면 앱 업데이트가 필요합니다. 예전 앱은 시즌 계산이 없어 그날 질문이 기본 순환이고, 시드된 시즌 질문 때문에 순환 순서가 바뀝니다.</li><li><strong>대안</strong>: 서버가 날마다 <code>appConfig</code>에 오늘의 질문을 쓰기(스케줄러·읽기 추가, 오프라인 위젯과 어긋남), 시드만 하고 앱은 그대로(그날 질문으로 고정되지 않음), 시즌 켜기·끄기 원격 설정(이번 시즌 범위 밖, 필요하면 다음 시즌에).</li></ul><h2 id="adr-36" tabindex="-1">ADR-36 PR마다 테스트, 변경 이력은 PR별 조각 파일 <a class="header-anchor" href="#adr-36" aria-label="Permalink to &quot;ADR-36 PR마다 테스트, 변경 이력은 PR별 조각 파일 {#adr-36}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: (1) PR과 <code>main</code> push마다 <strong>Test</strong> 워크플로(<code>.github/workflows/test.yml</code>)가 클라이언트·함수 단위, 보안 규칙(에뮬레이터), 함수 엔드투엔드, 웹 빌드(<code>.env.emulator</code>), 문서 빌드를 job별로 나란히 돌리고, 바뀐 경로에 해당하지 않는 job은 건너뜁니다. 결과는 늘 도는 <strong>Test summary</strong> job 하나로 모아 필수 검사로 쓸 수 있게 합니다. 비밀값·Google 자격 증명은 쓰지 않습니다. (2) 변경 이력은 PR마다 <code>docs/changelog/unreleased/&lt;티켓&gt;.md</code> 조각 하나로 쓰고, 배포할 때 <code>npm run changelog</code>(<code>scripts/mergeChangelog.mjs</code>)가 날짜를 붙여 <code>changelog.md</code>로 옮깁니다. 문서 사이트는 조각을 변경 이력 맨 위 &quot;아직 합치지 않은 변경&quot;에 보여 줍니다(VitePress 데이터 로더). → <a href="/grato-docs/operations/testing#ci">CI 테스트</a>, <a href="/grato-docs/contributing-docs#changelog">변경 이력 쓰기</a></li><li><strong>이유</strong>: 테스트가 배포 워크플로에서만 돌아 오너가 PR을 병합해도 되는지 GitHub에서 바로 알 수 없었고, 규칙 테스트는 에이전트 환경에서 에뮬레이터를 받을 수 없어 아예 돌지 못했습니다. 변경 이력은 모든 PR이 같은 맨 위 줄에 써서 열린 PR끼리 늘 충돌했습니다(2026-10-17, PR 4개). 파일을 나누면 같은 줄을 고치지 않으므로 충돌이 생기지 않습니다.</li><li><strong><code>merge=union</code>을 쓰지 않은 이유</strong>: <code>.gitattributes</code>의 <code>merge=union</code>은 로컬 <code>git merge</code>에서는 두 쪽 줄을 모두 남기지만, GitHub 병합 버튼이 이를 따른다는 공식 문서가 없고, 따르지 않는다는 보고가 있습니다(rubocop PR #3594, 2016: &quot;GitHub doesn&#39;t support the feature&quot;). GitLab도 웹 병합이 <code>merge=union</code>을 따르지 않아(이슈 17325) 변경 이력을 조각 파일로 바꿨습니다. 확실하지 않아 쓰지 않습니다. 따른다 해도 항목 순서가 뒤섞이고 빈 줄·제목이 잘못 합쳐질 수 있습니다.</li><li><strong>알려진 한계</strong>: 조각은 사이트에서 HTML로 그려 문서 빌드의 깨진 링크 검사를 받지 않아, <code>mergeChangelog.mjs --check</code>(CI 문서 job)가 형식·중복 id·링크한 페이지가 있는지를 대신 봅니다(앵커는 보지 않음). 합치기는 사람이(또는 PO 에이전트가) 배포 때 PR로 해야 합니다. 경로 필터가 놓친 의존이 있으면 PR에서 job이 건너뛰어질 수 있어 <code>main</code> push에서는 모두 돌립니다.</li><li><strong>대안</strong>: <code>merge=union</code>(위), PR마다 손으로 충돌 정리(지금 상태, PO 시간), 변경 이력을 PR 본문에서 자동 생성(사용자 관점 요약이 사라짐), 외부 도구(changesets 등, 패키지 배포용이라 맞지 않음).</li></ul><h2 id="adr-37" tabindex="-1">ADR-37 이미지 테마: 배지로 서버가 지급, 고르기와 그리기는 기기에서 <a class="header-anchor" href="#adr-37" aria-label="Permalink to &quot;ADR-37 이미지 테마: 배지로 서버가 지급, 고르기와 그리기는 기기에서 {#adr-37}&quot;">​</a></h2><ul><li><strong>결정 (2026-10, GRATO-35)</strong>: 캘린더·배지·감사 글·초대장 이미지의 테마(겨울·신년)는 운영자가 배지에 다는 보상입니다(<code>badges/{id}.theme</code>). <code>evaluateBadges</code>가 가진 배지의 테마를 <code>userBadges.themes</code>에 넣고 빼지 않습니다(호칭·보상 공감과 같은 방식, <a href="#adr-23">ADR-23</a>·<a href="#adr-24">ADR-24</a>). 앱은 받은 테마만 고르기 칩에 보이고(잠금·가격 없음), 고른 테마로 기기 안에서 캔버스에 그립니다. 고른 값은 기기에만 둡니다. 토큰·장식은 <code>src/lib/themes.js</code> 한 곳, id 목록은 앱·함수 JSON·규칙 세 곳을 테스트로 같게 둡니다. → <a href="/grato-docs/features/stats-badges#themes">이미지 테마</a></li><li><strong>이유</strong>: 시즌 배지 = 호칭 + 테마로 &quot;한 번 받은 것은 빼앗지 않는다&quot;를 지키려면 지급 기록이 서버에 있어야 합니다. 그리기는 이미 캘린더 이미지가 쓰는 기기 캔버스 방식이라 서버 비용·저장 공간이 없고, 감사 글 내용이 서버 이미지 생성에 쓰이지 않습니다. 고른 테마를 서버에 쓰지 않아 새 쓰기 경로·규칙이 필요 없습니다. 배지에 테마를 달지 않으면 지급이 없어 앱 업데이트 없이 끌 수 있습니다.</li><li><strong>초대장</strong>: 이미지에 초대 코드를 넣지 않습니다. 이미지만 따로 퍼져도 코드가 새지 않게, 코드는 함께 보내는 초대 메시지(링크)에만 둡니다. 받는 사람은 이미지와 링크를 함께 받습니다(&quot;받는 사람에게도 보임&quot;). 초대 페이지(<code>/invite/{code}</code>) 자체를 테마로 꾸미는 것은 하지 않았습니다(초대 코드 문서에 테마를 저장해야 해서 서버 변경이 커짐).</li><li><strong>예전 앱</strong>: 1.0.1 (4) 이하는 <code>themes</code> 필드를 읽지 않아 늘 기본 모습입니다. 모르는 테마 id는 어느 앱에서나 기본으로 그립니다.</li><li><strong>대안</strong>: 고른 테마를 <code>users</code>에 저장하고 규칙으로 확인(기기 사이에 이어지지만 쓰기 경로·get 1회가 늘고, 이미지 하나 고르는 일에 비해 과함), 서버에서 이미지 생성(비용, 글 내용을 서버로 보냄), 테마를 날짜로 모두에게 열기(보상이 아니게 됨, GRATO-66 명세와 다름).</li></ul><h2 id="adr-38" tabindex="-1">ADR-38 올해의 감사 돌아보기: 기기 안 계산, 설정 문서로 켜고 끄기 <a class="header-anchor" href="#adr-38" aria-label="Permalink to &quot;ADR-38 올해의 감사 돌아보기: 기기 안 계산, 설정 문서로 켜고 끄기 {#adr-38}&quot;">​</a></h2><ul><li><strong>결정 (2026-10)</strong>: 마이페이지 &quot;올해 돌아보기&quot;는 그해 내 글(<code>userId == 나</code>, KST 달마다 한 쿼리)을 기기에서 읽어 순수 함수(<code>src/lib/yearReview.js</code>)로 요약합니다. 서버 집계·새 컬렉션을 만들지 않습니다. 켜는 기간은 앱 안 기본값 하나(12-01..01-31 KST)와 <code>appConfig/yearReview</code>(<code>enabled</code>, <code>start</code>, <code>end</code>, 설정 스크립트만 씀)로 정하고, 문서가 없거나 읽지 못하면 기본값입니다. 공유 이미지는 기본이 숫자 없음이고 글 제목·내용을 넣지 않습니다. → <a href="/grato-docs/features/stats-badges#year-review">올해의 감사 돌아보기</a></li><li><strong>이유</strong>: 회고는 나만 보는 정보이고, 필요한 값(기록한 날, 달, 처음 쓴 날, 다시 읽을 글)은 내 글만으로 나옵니다. 서버 집계를 두면 함수·백필·규칙이 늘고 글 내용(제목)을 다른 문서로 옮기게 됩니다. 날짜를 코드에 박으면 시즌 시작이 바뀔 때(11/30 → 11/15, 돌아보기는 12/1) 앱 심사를 다시 거쳐야 하고, 문제가 생겨도 끌 수 없습니다. 설정 문서를 못 읽을 때 기본값으로 켜는 것은 오프라인·규칙 배포 전에도 시즌 화면이 나오게 하려는 것입니다.</li><li><strong>알려진 한계</strong>: 글이 많은 사람은 마이페이지를 열 때 그해 글 수만큼 읽습니다(지난달은 세션 캐시, 이번 달만 다시). 웹 SDK는 필드만 골라 읽을 수 없어 문서 전체를 받고, 메모리에는 필요한 필드만 둡니다. 달마다 500개를 넘으면 그 달은 500개까지만 셉니다. 꺼도 이미 열린 앱은 다시 열어야 반영됩니다.</li><li><strong>대안</strong>: <code>userStats</code>에 연도별 집계 추가(서버 변경·백필, 다시 읽을 글은 여전히 쿼리 필요), 연도 전체 한 쿼리(상한에 걸리면 숫자가 틀림), 날짜 하드코딩(시즌 변경에 앱 업데이트 필요).</li></ul><h2 id="adr-39" tabindex="-1">ADR-39 CI/CD: 웹은 PR 미리보기, iOS는 Xcode Cloud, Android는 GitHub Actions <a class="header-anchor" href="#adr-39" aria-label="Permalink to &quot;ADR-39 CI/CD: 웹은 PR 미리보기, iOS는 Xcode Cloud, Android는 GitHub Actions {#adr-39}&quot;">​</a></h2><ul><li><strong>결정 (2026-10, GRATO-94)</strong>: (1) <strong>웹</strong>: 운영 배포는 지금처럼 수동 + 오너 승인(<code>deploy.yml</code>, <a href="#adr-36">ADR-36</a>과 <a href="/grato-docs/operations/deploy#ci">CI로 배포</a>)이고, 같은 저장소 PR에서 Test가 통과하면 Firebase Hosting 미리보기 채널 <code>pr-&lt;번호&gt;</code>(7일)에 올려 PR에 링크를 답니다(<code>preview.yml</code>). 미리보기는 승인 없이 돌되 운영과 다른 Environment(<code>preview</code>)·WIF 풀·서비스 계정을 쓰고, PR 코드가 도는 job에는 자격 증명을 주지 않습니다. (2) <strong>iOS</strong>: Apple의 <strong>Xcode Cloud</strong>가 저장소의 <code>ios/App/ci_scripts/</code>로 웹 빌드·<code>cap sync</code>를 하고 Archive → TestFlight 내부 테스트까지 합니다. 시작은 손으로 또는 <code>release/ios-*</code> 태그. (3) <strong>Android</strong>: GitHub Actions <code>android-release.yml</code>(수동, Environment <code>production</code> 승인)이 AAB를 만들어 업로드 키로 서명하고 Play <strong>내부 테스트</strong> 트랙에 올립니다. 스토어 심사 제출·프로덕션 트랙·스토어 문구는 어느 쪽도 자동으로 하지 않습니다. → <a href="/grato-docs/operations/deploy#ci-preview">PR 웹 미리보기</a>, <a href="/grato-docs/operations/ci-mobile">앱 빌드 CI</a></li><li><strong>이유</strong>: 저장소가 비공개(개인 계정)라 GitHub의 macOS 러너는 분을 10배로 셉니다. Xcode Cloud는 Apple Developer Program에 월 25 컴퓨트 시간이 포함되고, 서명·프로비저닝을 Apple이 관리해 인증서·프로필을 GitHub 비밀값으로 옮기지 않아도 됩니다. Android 빌드는 Linux 러너로 충분하고, 이미 있는 Environment <code>production</code> 승인과 비밀값 관리 방식을 그대로 씁니다. 웹 미리보기는 오너가 병합 전에 화면을 휴대폰에서 바로 볼 수 있게 합니다.</li><li><strong>미리보기 권한</strong>: Hosting IAM은 사이트 단위라 &quot;채널만&quot; 쓰는 역할이 없습니다. 미리보기 계정은 운영 채널에도 올릴 수 있으므로, 토큰을 <code>main</code>의 <code>preview.yml</code> + <code>preview</code> Environment로만 발급하고 운영과 다른 풀을 씁니다(같은 풀이면 미리보기 토큰으로 운영 배포 계정을 빌릴 수 있음). 역할(기본/사용자 지정/별도 프로젝트)과 Auth 승인 도메인 권한은 오너가 고릅니다.</li><li><strong>알려진 한계</strong>: <s>미리보기는 운영 Firebase 프로젝트의 데이터·함수·규칙에 붙습니다</s> → <a href="#adr-40">ADR-40</a>으로 stg 프로젝트에 붙게 바뀌었습니다(서버 변경은 미리보기에 없음). PR이 바꾼 <code>firebase.json</code>은 미리보기에 반영되지 않습니다. <code>preview.yml</code>은 <code>main</code>에 들어간 뒤부터 동작합니다. Xcode Cloud는 월 25시간을 넘으면 유료 요금제가 필요하고, Apple이 붙이는 빌드 번호가 TestFlight 번호가 됩니다.</li><li><strong>대안</strong>: iOS를 GitHub Actions macOS 러너 + fastlane match(비공개 저장소에서 분 비용, 인증서·프로필을 비밀값으로 관리), 앱 둘 다 맥에서 손으로(지금, 오너 시간), 미리보기를 별도 Firebase 프로젝트로 완전히 분리(공유 페이지 재작성이 동작하지 않고 Auth는 어차피 운영), 웹을 PR 병합 때 자동 운영 배포(오너 승인 원칙과 다름).</li></ul><h2 id="adr-40" tabindex="-1">ADR-40 환경 분리: dev(에뮬레이터) · stg(별도 Firebase 프로젝트) · prod(수동) <a class="header-anchor" href="#adr-40" aria-label="Permalink to &quot;ADR-40 환경 분리: dev(에뮬레이터) · stg(별도 Firebase 프로젝트) · prod(수동) {#adr-40}&quot;">​</a></h2><ul><li><strong>결정 (2026-10, GRATO-103)</strong>: 환경을 셋으로 나눕니다. <strong>dev</strong>는 지금처럼 로컬 에뮬레이터(<code>demo-grato</code>). <strong>stg</strong>는 새 Firebase 프로젝트 <code>grato-stg</code>(Hosting·Auth·Firestore·Storage·Functions·Cloud Tasks 전부, 규칙·인덱스는 운영과 같은 파일, 테스트 계정·가짜 데이터만, 이메일 로그인만). <strong>prod</strong>는 <code>grato-44d47</code>, 오너가 손으로만 배포. PR 웹 미리보기는 stg의 Hosting 채널로, Deploy 워크플로는 입력 <code>target-env</code>(기본 <code>stg</code>)로 대상을 고르고(<code>staging</code>/<code>production</code> Environment, 프로젝트 ID를 워크플로가 대조) prod는 <code>main</code>에서만. 같은 일을 하는 풀·서비스 계정은 환경마다 따로(stg 안에서도 배포용·미리보기용 분리, 운영 풀 재사용 금지). Hosting 사이트는 <code>firebase.json</code>의 <code>target: app</code> + <code>.firebaserc</code> <code>targets</code>로 프로젝트마다 정합니다. 웹 빌드는 <code>build:stg</code>(<code>.env.stg</code>). 시드·백필·설정 스크립트는 대상 프로젝트를 검사해 운영에는 <code>GRATO_CONFIRM_PROJECT</code>가 있어야만 돕니다. → <a href="/grato-docs/operations/deploy#environments">환경</a></li><li><strong>이유</strong>: 미리보기와 리허설이 운영 데이터를 건드리면 테스트 계정으로만 쓴다는 약속에 기댈 수밖에 없고(ADR-39의 알려진 한계), Hosting 권한이 사이트 단위라 미리보기 계정이 운영 사이트에도 올릴 수 있었습니다. 별도 프로젝트면 권한·데이터가 구조로 갈립니다. 서버 배포 순서(규칙 → 인덱스 → 함수 → 시드 → Hosting)와 백필을 운영 전에 stg에서 같은 순서로 돌려 볼 수 있고, 시즌 날짜 테스트도 운영 영향이 없습니다.</li><li><strong>비용·한계</strong>: Blaze 요금(거의 0원대), 환경별 설정 한 벌(<code>.env.stg</code>, Environment 변수, WIF) 더. stg에는 Google·Apple 로그인, APNs, 웹 푸시, 커스텀 도메인이 없고 공유 링크 문구는 <code>grato.today</code>를 가리킵니다. 앱(iOS·Android) stg 빌드는 이번 범위 밖(1.0.2 이후 필요하면). stg 배포 워크플로는 브랜치 제한이 없어(리허설) PR 브랜치의 워크플로가 stg 자격 증명을 쓸 수 있지만 stg에는 실제 데이터가 없습니다. 병합 때 stg 자동 배포는 아직 없음(결정 필요). <code>.firebaserc</code>의 <code>default</code>는 운영으로 남겨 두었습니다.</li><li><strong>대안</strong>: 운영 프로젝트에서 미리보기 권한만 줄이기(GRATO-98의 A/B/C: 기본 역할/사용자 지정 역할/미리보기 전용 Hosting 프로젝트) — 데이터 분리가 안 되어 채택하지 않음. 미리보기만 별도 프로젝트로 하는 안 — 서버 리허설을 못 해서 채택하지 않음.</li></ul>',84)])])}const q=e(a,[["render",i]]);export{h as __pageData,q as default};
